49		private static void render(GuiGraphics guiGraphics, int width, int height) {
50			if (startedAt < 0) return;
51			long elapsed = System.currentTimeMillis() - startedAt;
52			if (elapsed > TUMBLE_MS + HOLD_MS + FADE_MS) {
53				startedAt = -1;
54				return;
55			}
56	
57			Font font = Minecraft.getInstance().font;
58			float alpha = elapsed <= TUMBLE_MS + HOLD_MS ? 1.0f : 1.0f - (elapsed - TUMBLE_MS - HOLD_MS) / (float) FADE_MS;
