22	/**
23	 * <p>Ephemeral summary of the most recent combat events (rolls, attacks, spells, death saves), bottom
24	 * right, with the same tome-like look as the rest of the HUD (see {@link GuiStyle}). <b>One line per
25	 * event, trimmed with an ellipsis, never wrapped</b>: the full detail (dice breakdown, against which AC,
26	 * damage type) lives ONLY in chat — having it in full in both places meant reading the same thing twice,
27	 * and this panel exists for a glance, not for reading.</p>
28	 *
29	 * <p>No new network message and no changes to any manager: EVERY combat line the mod produces already
30	 * reaches the client as chat and already starts with a translatable {@code chat.dndsheets.tag.*} tag
31	 * (see {@code ChatFeedback.tag}); this class only recognizes those lines as they arrive and summarizes
32	 * them on screen for a while. That's why {@link #push} is private: nobody can write to this panel
33	 * directly — if a line didn't go through {@code ChatFeedback}, it doesn't exist for this panel.</p>
34	 */
35	@Mod.EventBusSubscriber(modid = DndsheetsMod.MODID, bus = Mod.EventBusSubscriber.Bus.MOD, value = Dist.CLIENT)
36	public class CombatLogOverlay {
37	
38		//Shrunk after the first real session ("interface felt cluttered"): fewer events, shorter lifetime,
39		//and less width — the panel is meant for a glance, not a second chat window competing with the real one.
40		private static final int MAX_ENTRIES = 4;
41		private static final long LIFE_MS = 8_000;
42		//Same floor as the other two panels (see TurnHudOverlay): any less and the text runs into the corner brace.
43		private static final int PADDING = 7;
44		private static final int LINE_HEIGHT = 9;
45		private static final int CONTENT_WIDTH = 170;
46	
47		private record Entry(Component line, long bornAt) {}
48	
49		private static final ArrayDeque<Entry> entries = new ArrayDeque<>();
50	
51		@SubscribeEvent
52		public static void registerOverlays(RegisterGuiOverlaysEvent event) {
53			event.registerAboveAll("dndsheets_combat_log", (gui, guiGraphics, partialTick, width, height) -> render(guiGraphics, width, height));
54		}
55	
56		//FORGE bus (game events), separate from the class's MOD bus (overlay registration).
57		@Mod.EventBusSubscriber(modid = DndsheetsMod.MODID, value = Dist.CLIENT)
58		public static class Chat {
59			@SubscribeEvent
60			public static void onSystemChat(ClientChatReceivedEvent.System event) {
61				if (!event.isOverlay() && hasModTag(event.getMessage())) push(event.getMessage());
62			}
63		}
64	
65		private static void push(Component line) {
66			//The semantic summary travels INSIDE the chat line itself, as an invisible insertion (see
67			//ChatFeedback.withSummary): if present, the panel shows THAT ("Wizard ▶ Creeper · 17 ✓ 6") and the
68			//breakdown stays chat-only. Without a summary (rare lines: falls, revivals), it falls back to the
69			//full trimmed line — better long than missing.
70			String summary = findSummary(line);
71			entries.addLast(new Entry(summary != null ? Component.literal(summary) : line, System.currentTimeMillis()));
72			while (entries.size() > MAX_ENTRIES) entries.removeFirst();
73		}
74	
75		@Nullable
76		private static String findSummary(Component component) {
77			String insertion = component.getStyle().getInsertion();
78			if (insertion != null && insertion.startsWith(net.hawthorn.dndsheets.ChatFeedback.SUMMARY_PREFIX)) {
79				return insertion.substring(net.hawthorn.dndsheets.ChatFeedback.SUMMARY_PREFIX.length());
80			}
81			for (Component sibling : component.getSiblings()) {
82				String found = findSummary(sibling);
83				if (found != null) return found;
84			}
85			return null;
86		}
87	
88		//The tag is the first chunk of every ChatFeedback line, but it can arrive nested inside the
89		//Component tree, so the search goes depth-first instead of just checking the root.
90		private static boolean hasModTag(Component component) {
91			if (component.getContents() instanceof TranslatableContents translatable
92				&& translatable.getKey().startsWith("chat.dndsheets.tag.")) return true;
93			for (Component sibling : component.getSiblings()) {
94				if (hasModTag(sibling)) return true;
95			}
96			return false;
97		}
98	
99		private static void render(GuiGraphics guiGraphics, int screenWidth, int screenHeight) {
100			long now = System.currentTimeMillis();
101			while (!entries.isEmpty() && now - entries.peekFirst().bornAt() > LIFE_MS) entries.removeFirst();
102			if (entries.isEmpty()) return;
103	
104			Font font = Minecraft.getInstance().font;
105	
106			//One line per event, trimmed and NEVER wrapped: this panel is the summary, the full breakdown is
107			//already in chat (explicit owner request: detail stays chat-only). substrByWidth respects the
108			//Component's styles, so trimming preserves ChatFeedback's colors.
109			List<FormattedCharSequence> wrapped = new ArrayList<>(entries.size());
110			int widest = 0;
111			int ellipsisWidth = font.width("…");
112			for (Entry entry : entries) {
113				FormattedCharSequence line;
114				if (font.width(entry.line()) <= CONTENT_WIDTH) {
115					line = entry.line().getVisualOrderText();
116				} else {
117					line = net.minecraft.locale.Language.getInstance().getVisualOrder(net.minecraft.network.chat.FormattedText.composite(
118						font.substrByWidth(entry.line(), CONTENT_WIDTH - ellipsisWidth),
119						net.minecraft.network.chat.FormattedText.of("…")));
120				}
121				wrapped.add(line);
122				widest = Math.max(widest, font.width(line));
123			}
124	
125			//Bottom right, above the hotbar: the corner the other two panels don't occupy, and where it
126			//doesn't cover either the chat (bottom-left) or the turn tracker (top-right).
127			int right = screenWidth - 8;
128			int left = right - widest - 2 * PADDING;
129			int bottom = screenHeight - 45;
130			int top = bottom - wrapped.size() * LINE_HEIGHT - 2 * PADDING + 4;
131	
132			GuiStyle.panel(guiGraphics, left, top, right, bottom);
133	
134			int y = top + PADDING - 2;
135			for (FormattedCharSequence piece : wrapped) {
136				guiGraphics.drawString(font, piece, left + PADDING, y, GuiStyle.SUBTITLE_COLOR);
137				y += LINE_HEIGHT;
138			}
139		}
140	}
