321		private void renderOverview(GuiGraphics g, JsonObject sheet) {
322			Player player = Minecraft.getInstance().player;
323			int plateW = (contentW() - 8) / 3;
324			int left = contentLeft();
325			int top = contentTop();
326	
327			//Row 1: HP (with a bar), AC, Speed.
328			int hp = player == null ? 0 : (int) Math.ceil(player.getHealth());
329			int maxHp = player == null ? 0 : (int) Math.ceil(player.getMaxHealth());
330			int temp = player == null ? 0 : (int) Math.ceil(player.getAbsorptionAmount());
331			plate(g, left, top, plateW, Icons.stat("hp"), Component.translatable("gui.dndsheets.sheet.hp"));
332			//Value on the same line as the other plates' values (y+14), bar under it: the value used to sit at
333			//y+8 and was drawn over the "Hit points" label (y+3).
334			int barX = left + 26;
335			int barY = top + 25;
336			int barW = plateW - 32;
337			g.fill(barX, barY, barX + barW, barY + 5, 0xFF0B0906);
338			double fraction = maxHp <= 0 ? 0 : Math.min(1.0, hp / (double) maxHp);
339			g.fill(barX + 1, barY + 1, barX + 1 + (int) ((barW - 2) * fraction), barY + 4, fraction > 0.5 ? GOOD : fraction > 0.25 ? GuiStyle.WARN_COLOR : BAD);
340			g.drawString(this.font, hp + " / " + maxHp + (temp > 0 ? "  +" + temp : ""), barX, top + 14, GuiStyle.TITLE_COLOR, false);
341	
342			int ac = player == null ? 10 : CombatManager.armorClassOf(player, sheet);
343			plate(g, left + plateW + 4, top, plateW, Icons.stat("ac"), Component.translatable("gui.dndsheets.sheet.ac"));
344			g.drawString(this.font, Integer.toString(ac), left + plateW + 4 + 26, top + 14, GuiStyle.TITLE_COLOR, false);
345	
346			plate(g, left + 2 * (plateW + 4), top, plateW, Icons.stat("speed"), Component.translatable("gui.dndsheets.character_sheet.label_speed"));
347	
348			//Row 2: Initiative, Proficiency, Passive Perception.
349			int row2 = top + PLATE_H + 4;
350			plate(g, left, row2, plateW, Icons.stat("initiative"), Component.translatable("gui.dndsheets.character_sheet.label_initiative"));
351			g.drawString(this.font, signed(bonusOf(expressionAt("checks", 6))), left + 26, row2 + 14, GuiStyle.TITLE_COLOR, false);
352			plate(g, left + plateW + 4, row2, plateW, Icons.stat("spell"), Component.translatable("gui.dndsheets.character_sheet.label_proficiency_bonus"));
353			g.drawString(this.font, signed(proficiency()) + "   " + Component.translatable("gui.dndsheets.sheet.level", level()).getString(), left + plateW + 4 + 26, row2 + 14, GuiStyle.TITLE_COLOR, false);
354			plate(g, left + 2 * (plateW + 4), row2, plateW, Icons.byPath("action/search"), Component.translatable("gui.dndsheets.sheet.passive"));
355			g.drawString(this.font, Integer.toString(PassiveScores.passivePerception(sheet)), left + 2 * (plateW + 4) + 26, row2 + 14, GuiStyle.TITLE_COLOR, false);
356	
357			//Ability tiles.
358			int tilesTop = top + 2 * (PLATE_H + 4) + 6;
359			int tileW = (contentW() - 5 * 4) / 6;
360			java.util.Arrays.fill(savePips, null);
361			for (int i = 0; i < 6; i++) {
362				int x = left + i * (tileW + 4);
363				g.fill(x, tilesTop, x + tileW, tilesTop + TILE_H, PANEL_DARK);
364				g.renderOutline(x, tilesTop, tileW, TILE_H, PANEL_EDGE);
365				Component name = Component.translatable("gui.dndsheets.sheet.abbr_" + ABBR_KEYS[i]);
366				g.drawCenteredString(this.font, name, x + tileW / 2, tilesTop + 3, GuiStyle.ACCENT_COLOR);
367				int mod = modOf(intOf(sheet, ABILITY_KEYS[i], 10));
368				g.drawCenteredString(this.font, signed(mod), x + tileW / 2, tilesTop + 12 + 14 + 2, GuiStyle.TITLE_COLOR);
369				//Save proficiency pip, under the save button.
370				boolean saveProf = RollIndex.isProficient(expressionAt("saves", i));
371				int pipX = x + tileW / 2 + 6;
372				int pipY = tilesTop + 12 + 14 + 14 + 17 + 1;
373				pip(g, pipX, pipY, PIP_BIG, saveProf);
374				savePips[i] = new int[] {pipX, pipY, saveProf ? 1 : 0};
375			}
376			//Wrapped to the panel: one long line ran past its right edge.
377			int hintY = tilesTop + TILE_H + 5;
378			for (var line : this.font.split(Component.translatable("gui.dndsheets.sheet.hint_overview"), contentW())) {
379				g.drawString(this.font, line, left, hintY, GuiStyle.MUTED_COLOR, false);
380				hintY += 10;
381			}
382			//Conditions at a glance (the Combat tab has the same row): fills the space below the tiles.
383			//Only if it fits above the footer (small windows / large GUI scales have less room).
384			if (hintY + 6 + 16 <= dialogTop() + dialogH - FOOTER) renderConditionsRow(g, sheet, left, hintY + 6);
385		}
