308				//doesn't reshuffle under the cursor every time the last one of a level gets spent.
309				int color = current[level] > 0 ? GuiStyle.SUBTITLE_COLOR : GuiStyle.MUTED_COLOR;
310				cachedColumns.add(new SlotColumn(
311					Component.translatable("gui.dndsheets.grimoire.slot_level", level),
312					Component.literal(current[level] + "/" + max[level]),
313					color));
314			}
315	
316			int limit = SpellRegistry.preparedLimitFor(sheet);
317			cachedPrepared = limit <= 0 ? null
318				: Component.translatable("gui.dndsheets.grimoire.prepared_count", SpellRegistry.preparedCount(sheet), limit);
319		}
