321		private void renderSlotTable(GuiGraphics guiGraphics) {
322			JsonObject sheet = SheetLoader.getClientSheet();
323			if (sheet == null) return;
324	
325			int version = SheetLoader.clientSheetVersion();
326			if (version != cachedSlotVersion) {
327				rebuildSlotTable(sheet);
328				cachedSlotVersion = version;
329			}
330	
331			if (cachedColumns.isEmpty()) {
332				guiGraphics.drawCenteredString(this.font, Component.translatable("gui.dndsheets.grimoire.no_slots"), this.width / 2, SUBTITLE_Y, GuiStyle.MUTED_COLOR);
333				return;
334			}
335	
336			int firstColumnCenter = (this.width - cachedColumns.size() * SLOT_COL_WIDTH) / 2 + SLOT_COL_WIDTH / 2;
337			for (int i = 0; i < cachedColumns.size(); i++) {
338				SlotColumn column = cachedColumns.get(i);
339				int x = firstColumnCenter + i * SLOT_COL_WIDTH;
340				guiGraphics.drawCenteredString(this.font, column.levelLabel(), x, SUBTITLE_Y, GuiStyle.MUTED_COLOR);
341				guiGraphics.drawCenteredString(this.font, column.countLabel(), x, SUBTITLE_Y + SLOT_ROW_STEP, column.color());
342			}
343			//To the right of the table, in the same band: how many are prepared out of how many can be.
344			if (cachedPrepared != null) {
345				guiGraphics.drawString(this.font, cachedPrepared,
346					firstColumnCenter + cachedColumns.size() * SLOT_COL_WIDTH, SUBTITLE_Y + SLOT_ROW_STEP / 2, GuiStyle.MUTED_COLOR, false);
347			}
348		}
349	
350		/** Sorted by level (cantrips first) so {@link #buildRows}'s headers fall into place on their own. */
351		private static List<KnownSpell> knownSpells() {
352			List<KnownSpell> result = new ArrayList<>();
353			JsonObject sheet = SheetLoader.getClientSheet();
354			if (sheet == null || !sheet.has("spells")) return result;
355	
356			JsonArray spells = sheet.getAsJsonArray("spells");
357			for (int i = 0; i < spells.size(); i++) {
358				JsonObject entry = spells.get(i).getAsJsonObject();
359				String id = entry.has("id") ? entry.get("id").getAsString() : "";
360				//Resolved here, not at paint time: the list's label is assembled by concatenating (level,
361				//school, "unprepared") and ListPickerScreen's search box filters on that already-assembled
362				//string, so the name has to go in translated. This runs on the CLIENT, so it comes out in its
363				//language.
364				String name = net.hawthorn.dndsheets.ContentNames.plain(
365					entry.has("name") ? entry.get("name").getAsString() : id);
366				int level = entry.has("level") ? entry.get("level").getAsInt() : 0;
367				boolean prepared = SpellRegistry.isPrepared(sheet, id);
368				//Same criterion updateButtons() already uses for the cast button: a cantrip doesn't have
369				//"level 0", it has the tag 5e gives it. Before, the whole list used to say "(lv. 0)" for every
370				//cantrip, which means nothing at the table and didn't distinguish a cantrip from a real spell
371				//just by looking at the list.
372				StringBuilder label = new StringBuilder(name);
373				label.append(level == 0
374					? Component.translatable("gui.dndsheets.grimoire.tag_cantrip").getString()
375					: Component.translatable("gui.dndsheets.grimoire.tag_level", level).getString());
376				//School and "unprepared" go IN the label because ListPickerScreen's search box filters on it:
377				//typing "evoc" or "unprep" filters without spending a screen row on a filter button.
378				if (entry.has("school")) label.append(" · ").append(entry.get("school").getAsString());
379				if (!prepared) label.append(Component.translatable("gui.dndsheets.grimoire.tag_unprepared").getString());
380				result.add(new KnownSpell(id, name, label.toString(), level, prepared, entry.has("school") ? entry.get("school").getAsString().toLowerCase(java.util.Locale.ROOT) : ""));
381			}
382			result.sort(java.util.Comparator.comparingInt(KnownSpell::level).thenComparing(KnownSpell::name));
383			return result;
384		}
385	}
