18	/**
19	 * <p>Shared base for "vertical list of buttons" screens: centered title + bordered panel behind a
20	 * {@link ButtonListWidget} that scrolls automatically when not all the buttons fit. Covers both the DM
21	 * Panel selectors (player, preset, trait, character option, attack to remove, monster action) and the
22	 * fixed-button menus (DM Panel, Turn mode) — a fixed menu is just a list that never needs to scroll.
23	 * Previously each one repeated the same layout constants, the {@code mouseScrolled} forwarding to the
24	 * list, and {@code isPauseScreen() -> false}.</p>
25	 *
26	 * <p>{@code init()} and {@code render()} are not {@code final}: a screen with extra content (a
27	 * subtitle, a fixed button below the list) can override them, call {@code super} first and add its own
28	 * on top — simpler than trying to anticipate every variant with parameters.</p>
29	 *
30	 * <p><b>Navigation:</b> if this screen was opened from another one (DM Panel, player selector...),
31	 * pass that screen as {@code parent}. Picking a row, pressing "&lt; Back" or Escape returns to
32	 * {@code parent} instead of closing the whole menu — previously only {@code CharacterOptionListScreen}
33	 * did this by hand; now it's the base class's default behavior. Without {@code parent} (root screens
34	 * like {@code DmPanelScreen}/{@code MonsterActionScreen}) it behaves as before: it closes the menu.</p>
35	 */
36	public abstract class ListPickerScreen extends Screen {
37		protected static final int BUTTON_HEIGHT = 20;
38		protected static final int SPACING = 4;
39		//A header is a label between rules: at the height of a button row there was extra space left above
40		//and below, and five of them (DM Panel) cost five visible list rows. See ButtonListWidget, which now
41		//takes each row's height from the button itself.
42		private static final int HEADER_HEIGHT = 11;
43		private static final int LIST_TOP = 30;
44		private static final int PANEL_PADDING = 10;
45		private static final int BACK_BUTTON_WIDTH = 50;
46		private static final int BACK_BUTTON_HEIGHT = 14;
47		//"< Back" and the title share the header row, so their coordinates have to come from the same
48		//constants. Previously the button was placed in init() and the title in render() independently, and
49		//they collided: the button landed at y=8..22 and the title at y=16..24, plus horizontal overlap as
50		//soon as the title got long ("Choose a class preset"). It read like duplicated text.
51		private static final int BACK_BUTTON_TOP = 10;
