62		//box grabs focus at once, so the letter ended up typed in it. Characters in the first instants are dropped.
63		private final long openedAt = net.minecraft.Util.getMillis();
64	
65		protected final Screen parent;
66		private ButtonListWidget list;
67		private EditBox searchBox;
68		private boolean searchActive;
69		//Survives rebuildWidgets(): several screens get rebuilt when the server sheet arrives
70		//(refreshIfOpen), and without this every arrival would wipe out whatever was typed in the search box
71		//mid-search.
72		private String lastQuery = "";
73		//Same as lastQuery, and for the same reason: marking a proficiency (SkillProficiencyScreen) sends
74		//the sheet to the server, the sheet comes back, refreshIfOpen rebuilds the screen — and the new list
75		//started back at the top every time. With eighteen skills that's scrolling back down after EVERY
76		//mark.
