138		protected final Button addRow(Component label, Button.OnPress onPress) {
139			//TomeButton, not Button: vanilla's gray stone button on top of a leather panel reads like a
140			//widget borrowed from another interface. Changing it here repaints, from the inside, the forty-
141			//plus screens hanging off this base, the same way GuiStyle did with its frames.
142			Button button = TomeButton.of(label, onPress, 0, 0, buttonWidth(), BUTTON_HEIGHT);
143			this.addWidget(button);
