167			searchActive = searchable() || allButtons.size() >= AUTO_SEARCH_MIN_ROWS;
168			if (searchActive) {
169				searchBox = new EditBox(this.font, (this.width - buttonWidth()) / 2, LIST_TOP, buttonWidth(), SEARCH_HEIGHT, Component.translatable("gui.dndsheets.common.search"));
