172				//at this point in init — filtering with the restored text is done by the applyFilter call below.
173				searchBox.setValue(lastQuery);
174				searchBox.setResponder(text -> {
175					lastQuery = text;
176					applyFilter();
177				});
178				this.addRenderableWidget(searchBox);
179				this.setInitialFocus(searchBox);
180			} else {
181				searchBox = null;
182			}
183	
184			list = new ButtonListWidget((this.width - buttonWidth()) / 2, listTop(), buttonWidth(), listHeight(), SPACING);
185			applyFilter();
186			//After applyFilter(): the scroll ceiling comes from the height of the rows the list currently
187			//has, and setScrollAmount clamps on its own if the list ended up shorter.
188			list.scrollTo(lastScroll);
189			this.addRenderableWidget(list);
190	
191			if (parent != null) {
192				this.addRenderableWidget(TomeButton.of(Component.translatable("gui.dndsheets.common.back"), b -> this.onClose(),
193					panelLeft() + 4, BACK_BUTTON_TOP, BACK_BUTTON_WIDTH, BACK_BUTTON_HEIGHT));
194			}
195		}
