197		//Rebuilds the visible list with whatever matches the typed text (everything, if there's no search
198		//box or it's empty) — O(n²) due to replaceRows' contains(), acceptable for content-sized lists
199		//(tens of rows, not thousands). Headers (null label) only show up with no filter: during a search
200		//only results remain, without labels for emptied-out sections.
201		private void applyFilter() {
202			String query = searchBox == null ? "" : searchBox.getValue().trim().toLowerCase(Locale.ROOT);
203			List<Button> visible = new ArrayList<>();
204			for (int i = 0; i < allButtons.size(); i++) {
205				String label = allLabels.get(i);
206				if (label == null ? query.isEmpty() : (query.isEmpty() || label.contains(query))) {
207					visible.add(allButtons.get(i));
208				}
209			}
210			list.replaceRows(visible);
211			noMatches = !query.isEmpty() && visible.isEmpty();
212		}
