234		public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
235			if ((keyCode == org.lwjgl.glfw.GLFW.GLFW_KEY_ENTER || keyCode == org.lwjgl.glfw.GLFW.GLFW_KEY_KP_ENTER)
236				&& searchBox != null && searchBox.isFocused()) {
237				String query = searchBox.getValue().trim().toLowerCase(Locale.ROOT);
238				for (int i = 0; i < allButtons.size(); i++) {
239					String label = allLabels.get(i);
240					Button b = allButtons.get(i);
241					if (label != null && b.active && (query.isEmpty() || label.contains(query))) {
