262		@Override
263		public void render(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTicks) {
264			this.renderBackground(guiGraphics);
265	
266			int left = panelLeft();
267			int right = this.width - left;
268			//The header sits at a fixed spot (further down), so the panel's top edge does too, instead of
269			//depending on listTop() — a screen with a subtitle (Spellbook) moves listTop() further down
270			//without leaving the title sticking out above the panel.
271			int top = 16 - PANEL_PADDING;
272			int bottom = listTop() + listHeight() + PANEL_PADDING;
273			GuiStyle.panel(guiGraphics, left, top, right, bottom);
274	
275			//With "< Back" the title is centered in the space LEFT to its right, not the whole screen:
276			//centered on the screen, a long title would run under the button.
277			int titleLeft = parent != null ? left + 4 + BACK_BUTTON_WIDTH : left;
278			guiGraphics.drawCenteredString(this.font, GuiStyle.title(this.title), (titleLeft + right) / 2, TITLE_Y, GuiStyle.TITLE_COLOR);
279			//Rule under the title: separates the header from the content without spending a whole row of
280			//height, which is what a real separator would cost in a scrolling list. Ornate (center diamond)
281			//only here — internal separators use the plain rule (see GuiStyle.ruleOrnate).
282			GuiStyle.ruleOrnate(guiGraphics, left + 8, right - 8, 28);
283	
284			Component empty = noMatches ? Component.translatable("gui.dndsheets.common.no_results", searchBox.getValue().trim())
285				: allButtons.isEmpty() && emptyMessage() == null ? Component.translatable("gui.dndsheets.common.empty")
286				: emptyMessage();
287			if (empty != null) {
288				guiGraphics.drawCenteredString(this.font, empty, this.width / 2, this.height / 2, GuiStyle.MUTED_COLOR);
289			}
290	
291			super.render(guiGraphics, mouseX, mouseY, partialTicks);
292		}
