package net.hawthorn.dndsheets.client.gui;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import javax.annotation.Nullable;
import net.hawthorn.dndsheets.ContentType;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * <p>Manages the content of one type: one row per entry that opens its editor (where the "Delete" button
 * lives, see {@link SmallFormScreen#showDeleteButton()}), plus "+ Add". It only knows about weapons/spells/
 * presets/feats/encounters (see {@code ContentTypeForms}) — traits and monsters use their own flows
 * ({@code TraitEditScreen}, template capture from {@code MonsterActionScreen}).</p>
 *
 * <p><b>Two sections, not one.</b> On top, what the DM created ({@code dm_created.json}); below, what the
 * pack provides. It used to show only the former, so opening "Encounters" without having created any gave
 * an empty screen despite having five loaded, playable encounters: it reads as if this manages nothing.
 * Editing a pack entry saves YOUR version with the same id in your file, and that's the one that wins on
 * load (see the order in {@code DndPaths.autoLoadAll}) — the pack itself isn't touched, since it's rewritten
 * from the jar on every startup.</p>
 */
public class ContentEntryListScreen extends ListPickerScreen {
	private final ContentType type;
	private final List<JsonObject> entries;
	private final List<JsonObject> fromPacks;

	private ContentEntryListScreen(ContentType type, List<JsonObject> entries, List<JsonObject> fromPacks, Screen parent) {
		super(Component.translatable(specFor(type).titleKey()), parent);
		this.type = type;
		this.entries = entries;
		this.fromPacks = fromPacks;
	}

	//Same criterion as DungeonPieceListScreen.open: the parent is whatever's on screen at that moment
	//(the screen that requested the list, or this same screen if it's an echo after saving/deleting).
	public static void open(ContentType type, String arrayJson, String packsJson) {
		Minecraft.getInstance().setScreen(new ContentEntryListScreen(type, parse(arrayJson), parse(packsJson),
			Minecraft.getInstance().screen));
	}

	private static List<JsonObject> parse(String arrayJson) {
		List<JsonObject> entries = new ArrayList<>();
		for (JsonElement el : JsonParser.parseString(arrayJson).getAsJsonArray()) entries.add(el.getAsJsonObject());
		return entries;
	}

	/**
	 * <p>Everything this menu needs to know about a content type: what its title is, what fields its
	 * form asks for, how to prefill it from an existing entry, and how to turn it back into JSON.</p>
	 *
	 * <p>This used to be FOUR parallel switches over the same enum, with the same cases in the same order.
	 * Adding a type meant remembering to touch all four, and forgetting one didn't give a compile error:
	 * it gave an {@code IllegalStateException} at runtime, when opening that particular menu.</p>
	 */
	private record FormSpec(String titleKey,
			List<ContentFormScreen.FieldSpec> fields,
			Function<JsonObject, Map<String, String>> prefill,
			Function<Map<String, String>, JsonObject> toJson) {
	}

	//TRAIT and MONSTER have no flat form: TRAIT uses TraitEditScreen (nested level/die tables)
	//and MONSTER doesn't have a UI yet. They carry only a title, and the switch names them explicitly
	//instead of letting them fall into a default branch that throws: this way the compiler forces a
	//decision about what a NEW type does.
	private static FormSpec specFor(ContentType type) {
		return switch (type) {
			case WEAPON -> new FormSpec("gui.dndsheets.content_entry.weapons",
				ContentTypeForms.weaponFields(), ContentTypeForms::weaponPrefill, ContentTypeForms::weaponToJson);
			case SPELL -> new FormSpec("gui.dndsheets.content_entry.spells",
				ContentTypeForms.spellFields(), ContentTypeForms::spellPrefill, ContentTypeForms::spellToJson);
			case PRESET -> new FormSpec("gui.dndsheets.content_entry.presets",
				ContentTypeForms.presetFields(), ContentTypeForms::presetPrefill, ContentTypeForms::presetToJson);
			case ENCOUNTER -> new FormSpec("gui.dndsheets.content_entry.encounters",
				ContentTypeForms.encounterFields(), ContentTypeForms::encounterPrefill, ContentTypeForms::encounterToJson);
			case FEAT -> new FormSpec("gui.dndsheets.content_entry.feats",
				ContentTypeForms.featFields(), ContentTypeForms::featPrefill, ContentTypeForms::featToJson);
			case MAGIC_ITEM -> new FormSpec("gui.dndsheets.content_entry.magic_items",
				ContentTypeForms.magicItemFields(), ContentTypeForms::magicItemPrefill, ContentTypeForms::magicItemToJson);
			case TRAIT -> new FormSpec("gui.dndsheets.content_entry.traits", null, null, null);
			case MONSTER -> new FormSpec("gui.dndsheets.content_entry.monsters", null, null, null);
		};
	}

	@Override
	protected boolean searchable() {
		return true;
	}

	@Override
	protected void buildRows() {
		for (JsonObject entry : entries) addEntryRow(entry);
		addRow(Component.translatable("gui.dndsheets.content_entry.add"), b -> openCreateForm());

		if (fromPacks.isEmpty()) return;
		addHeader(Component.translatable("gui.dndsheets.content_entry.from_pack"));
		//Ids you already have your own version of aren't repeated below: your version is the one that
		//counts, and showing it twice — one editable, one not — only invites editing the one that doesn't count.
		java.util.Set<String> mine = new java.util.HashSet<>();
		for (JsonObject entry : entries) if (entry.has("id")) mine.add(entry.get("id").getAsString());
		for (JsonObject entry : fromPacks) {
			if (entry.has("id") && mine.contains(entry.get("id").getAsString())) continue;
			addEntryRow(entry);
		}
	}

	private void addEntryRow(JsonObject entry) {
		String id = entry.has("id") ? entry.get("id").getAsString() : "?";
		String name = entry.has("name") ? entry.get("name").getAsString() : id;
		//A pack name is a language key ("content.dndsheets.encounter.crypt_guardians"): it gets translated, which
		//is what the DM recognizes. Whatever the DM types is their own text and ContentNames leaves it as-is.
		Component label = Component.literal(id + " — ").append(net.hawthorn.dndsheets.ContentNames.of(name));
		addRow(id.equals(name) ? Component.literal(id) : label, b -> openEditor(entry));
	}

	//TRAIT has its own nested lists (level/die) that don't fit ContentFormScreen — see
	//TraitEditScreen. Everything else uses the generic flat form.
	private void openEditor(JsonObject entry) {
		String id = entry.get("id").getAsString();
		if (type == ContentType.TRAIT) {
			TraitEditScreen.open(entry);
		} else {
			FormSpec spec = specFor(type);
			ContentFormScreen.open(type, Component.translatable("gui.dndsheets.content_entry.edit", id).getString(),
				spec.fields(), spec.prefill().apply(entry), spec.toJson(), entry);
		}
	}

	//For TRAIT, "+ Add" only asks for id/name/characteristic (it creates the entry with empty level
	//tables); the tables get added by editing the newly created entry from TraitEditScreen.
	private void openCreateForm() {
		if (type == ContentType.TRAIT) {
			ContentFormScreen.open(type, Component.translatable("gui.dndsheets.content_entry.add_trait").getString(),
				ContentTypeForms.traitCreateFields(), Map.of(), ContentTypeForms::traitCreateToJson);
		} else {
			FormSpec spec = specFor(type);
			ContentFormScreen.open(type,
				Component.translatable("gui.dndsheets.content_entry.add_to",
					Component.translatable(spec.titleKey()).getString().toLowerCase(java.util.Locale.ROOT)).getString(),
				spec.fields(), Map.of(), spec.toJson());
		}
	}

	@Nullable
	@Override
	protected Component emptyMessage() {
		return entries.isEmpty() && fromPacks.isEmpty()
			? Component.translatable("gui.dndsheets.content_entry.empty") : null;
	}
}

package net.hawthorn.dndsheets.client.gui;

import com.google.gson.JsonObject;
import net.hawthorn.dndsheets.ContentType;
import net.hawthorn.dndsheets.DndsheetsMod;
import net.hawthorn.dndsheets.network.ContentEntryRemoveMessage;
import net.hawthorn.dndsheets.network.ContentEntrySaveMessage;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * <p>Generic form for content types whose schema is a flat object with no nested lists (weapons, spells,
 * presets — see {@code ContentTypeForms}): instead of a hand-built screen per type (like
 * {@code AddMonsterAttackScreen}/{@code AddTurnEffectScreen}), a single data-driven screen driven by a
 * list of {@link FieldSpec}. Traits (level/die lists) and monsters (attacks) don't fit here — see
 * {@code TraitEditScreen} and the template capture in {@code MonsterActionScreen}.</p>
 */
public class ContentFormScreen extends SmallFormScreen {
	public enum FieldKind { TEXT, INT, CYCLE, PICK }

	public record FieldSpec(String key, String label, FieldKind kind, String defaultValue, String[] cycleOptions, int maxLength,
							String source, boolean multi) {
		public static FieldSpec text(String key, String label, String defaultValue) {
			return text(key, label, defaultValue, 64);
		}

		/** With its own cap: for fields holding a comma-separated LIST, where 64 falls short. */
		public static FieldSpec text(String key, String label, String defaultValue, int maxLength) {
			return new FieldSpec(key, label, FieldKind.TEXT, defaultValue, null, maxLength, null, false);
		}

		/** A registry item id: a text box plus a button that opens the icon picker ({@link ItemPickerScreen}). */
		public static FieldSpec item(String key, String label, String defaultValue) {
			return pick(key, label, defaultValue, "ITEM", false, 64);
		}

		/**
		 * A text box (still editable by hand) plus a "..." button that opens {@link ChoiceScreen} for {@code source}
		 * (ITEM, SPELL, TRAIT, MONSTER, WEAPON, MAGIC_ITEM, CLASS, ENCHANTMENT, CONDITION, EFFECT, CREATURE_TYPE,
		 * DAMAGE_AFFINITY). {@code multi} = the box holds a comma-separated list.
		 */
		public static FieldSpec pick(String key, String label, String defaultValue, String source, boolean multi, int maxLength) {
			return new FieldSpec(key, label, FieldKind.PICK, defaultValue, null, maxLength, source, multi);
		}

		public static FieldSpec intField(String key, String label, String defaultValue) {
			return new FieldSpec(key, label, FieldKind.INT, defaultValue, null, 8, null, false);
		}

		public static FieldSpec cycle(String key, String label, String[] options) {
			return new FieldSpec(key, label, FieldKind.CYCLE, options[0], options, 0, null, false);
		}
	}

	//A form of up to SINGLE_PAGE_MAX fields stays on ONE page (weapon, preset... as always); a longer one (spell with
	//its effect/area fields, magic item) splits in pages of PAGE_SIZE with a button to flip. 8 + the page button +
	//Confirm is as tall as the old 10-field form, so it fits wherever that one did.
	private static final int SINGLE_PAGE_MAX = 10;
	private static final int PAGE_SIZE = 8;

	private final ContentType type;
	private final List<FieldSpec> fields;
	private final Map<String, String> prefill;
	private final Function<Map<String, String>, JsonObject> toJson;
	//The entry as it was before editing (null when creating): whatever the form doesn't manage is kept.
	private final JsonObject original;
	private int page = 0;

	private final Map<String, EditBox> textBoxes = new LinkedHashMap<>();
	private final Map<String, CycleField> cycleFields = new LinkedHashMap<>();
	//What was typed so far: survives the rebuilds (picker return, page flip), which would otherwise reset
	//every field to its prefill.
	private final Map<String, String> current = new LinkedHashMap<>();

	private ContentFormScreen(ContentType type, String title, List<FieldSpec> fields, Map<String, String> prefill,
			Function<Map<String, String>, JsonObject> toJson, JsonObject original, Screen parent) {
		super(Component.literal(title), Math.max(1, (Math.min(fields.size(), fields.size() <= SINGLE_PAGE_MAX ? fields.size() : PAGE_SIZE + 1) + 2) / 2), parent);
		this.type = type;
		this.fields = fields;
		this.prefill = prefill;
		this.toJson = toJson;
		this.original = original;
	}

	/** Empty {@code prefill} = blank form (create); with data = edit, see {@code ContentTypeForms}. */
	public static void open(ContentType type, String title, List<FieldSpec> fields, Map<String, String> prefill,
			Function<Map<String, String>, JsonObject> toJson) {
		open(type, title, fields, prefill, toJson, null);
	}

	/** Editing: {@code original} is the entry being edited, so the keys the form doesn't manage survive the save. */
	public static void open(ContentType type, String title, List<FieldSpec> fields, Map<String, String> prefill,
			Function<Map<String, String>, JsonObject> toJson, JsonObject original) {
		Minecraft.getInstance().setScreen(new ContentFormScreen(type, title, fields, prefill, toJson, original, Minecraft.getInstance().screen));
	}

	//The id can't be edited once created: ContentEntrySaveMessage upserts by id, so changing it in
	//an EDIT form would leave the old entry orphaned in dm_created.json instead of renaming it.
	//What marks "edit" is already having an id, not having prefill data: the encounter designer
	//opens this form with the composition filled in and the id still to be set.
	private List<FieldSpec> editableFields() {
		List<FieldSpec> list = new java.util.ArrayList<>();
		for (FieldSpec field : fields) {
			if (!(field.key().equals("id") && prefill.containsKey("id"))) list.add(field);
		}
		return list;
	}

	private int pageSize() {
		int n = editableFields().size();
		return n <= SINGLE_PAGE_MAX ? Math.max(1, n) : PAGE_SIZE;
	}

	private int pageCount() {
		return Math.max(1, (editableFields().size() + pageSize() - 1) / pageSize());
	}

	@Override
	protected void buildForm() {
		textBoxes.clear();
		cycleFields.clear();
		List<FieldSpec> all = editableFields();
		int from = Math.min(page, pageCount() - 1) * pageSize();
		for (FieldSpec field : all.subList(from, Math.min(all.size(), from + pageSize()))) {
			String initial = current.getOrDefault(field.key(), prefill.getOrDefault(field.key(), field.defaultValue()));
			if (field.kind() == FieldKind.CYCLE) {
				int startIndex = Math.max(0, indexOf(field.cycleOptions(), initial));
				cycleFields.put(field.key(), addCycleButton(field.label(), field.cycleOptions(), field.cycleOptions(), startIndex));
			} else if (field.kind() == FieldKind.PICK) {
				int y = nextRowY();
				int left = centerX - formWidth() / 2;
				EditBox box = addFieldAt(field.label(), initial, field.maxLength(), y, left, formWidth() - 24);
				textBoxes.put(field.key(), box);
				this.addRenderableWidget(net.hawthorn.dndsheets.client.gui.components.TomeButton.of(Component.literal("..."), b -> {
					snapshot();
					ChoiceScreen.request(field.source(), field.multi(), textBoxes.get(field.key()).getValue(), text -> textBoxes.get(field.key()).setValue(text));
				}, left + formWidth() - 20, y, 20, FIELD_HEIGHT));
			} else {
				textBoxes.put(field.key(), addField(field.label(), initial, field.maxLength()));
			}
		}
		if (pageCount() > 1) {
			int y = nextRowY();
			this.addRenderableWidget(net.hawthorn.dndsheets.client.gui.components.TomeButton.of(
				Component.translatable("gui.dndsheets.form.page", page + 1, pageCount()), b -> {
					snapshot();
					page = (page + 1) % pageCount();
					this.rebuildWidgets();
				}, centerX - formWidth() / 2, y, formWidth(), FIELD_HEIGHT));
		}
	}

	private static int indexOf(String[] options, String value) {
		for (int i = 0; i < options.length; i++) {
			if (options[i].equalsIgnoreCase(value)) return i;
		}
		return 0;
	}

	//Prefill + defaults for every field, i.e. what the form holds before the DM touches anything.
	private Map<String, String> initialValues() {
		Map<String, String> values = new LinkedHashMap<>();
		if (prefill.containsKey("id")) values.put("id", prefill.get("id"));
		for (FieldSpec field : editableFields()) values.put(field.key(), prefill.getOrDefault(field.key(), field.defaultValue()));
		return values;
	}

	@Override
	protected void onConfirm() {
		snapshot();
		Map<String, String> values = initialValues();
		for (Map.Entry<String, String> entry : current.entrySet()) values.put(entry.getKey(), entry.getValue().trim());

		JsonObject entry = toJson.apply(values);
		if (!entry.has("id") || entry.get("id").getAsString().isBlank()) return;
		if (original != null) entry = mergeWithOriginal(entry);

		DndsheetsMod.PACKET_HANDLER.sendToServer(new ContentEntrySaveMessage(type, entry.toString()));
	}

	//Editing rewrites the whole entry, so anything the form has no field for (a spell's summon, a weapon's
	//custom model...) used to vanish silently — and editing an imported entry saves a copy that takes
	//precedence, so it silently broke the original. Keys the form owns (the ones it emits for the untouched
	//entry, plus its field keys) are replaced by the form's answer, which also lets a blanked field really
	//remove its key; every other key of the original is carried over as-is.
	private JsonObject mergeWithOriginal(JsonObject fromForm) {
		java.util.Set<String> owned = new java.util.HashSet<>(fromForm.keySet());
		for (FieldSpec field : fields) owned.add(field.key());
		try {
			owned.addAll(toJson.apply(initialValues()).keySet());
		} catch (RuntimeException ignored) {
			//A form that can't render the untouched entry only loses the "blank removes the key" nicety.
		}
		JsonObject merged = new JsonObject();
		for (Map.Entry<String, com.google.gson.JsonElement> kept : original.entrySet()) {
			if (!owned.contains(kept.getKey())) merged.add(kept.getKey(), kept.getValue());
		}
		for (Map.Entry<String, com.google.gson.JsonElement> own : fromForm.entrySet()) merged.add(own.getKey(), own.getValue());
		return merged;
	}

	//Only when editing (there's an already-created id to delete) — when creating there's nothing to delete yet.
	@Override
	protected boolean showDeleteButton() {
		return prefill.containsKey("id");
	}

	@Override
	protected void onDelete() {
		DndsheetsMod.PACKET_HANDLER.sendToServer(new ContentEntryRemoveMessage(type, prefill.get("id")));
	}

	/** The item-id text boxes: drop targets for JEI's ghost drag (see compat/DndJeiPlugin). */
	public List<EditBox> itemBoxes() {
		List<EditBox> boxes = new java.util.ArrayList<>();
		for (FieldSpec field : fields) {
			EditBox box = field.kind() == FieldKind.PICK && "ITEM".equals(field.source()) && !field.multi() ? textBoxes.get(field.key()) : null;
			if (box != null) boxes.add(box);
		}
		return boxes;
	}

	/** The panel's column, so JEI keeps its item list clear of the form. */
	public net.minecraft.client.renderer.Rect2i panelArea() {
		return new net.minecraft.client.renderer.Rect2i(centerX - formWidth() / 2 - 12, 0, formWidth() + 24, this.height);
	}

	private void snapshot() {
		for (Map.Entry<String, EditBox> entry : textBoxes.entrySet()) current.put(entry.getKey(), entry.getValue().getValue());
		for (Map.Entry<String, CycleField> entry : cycleFields.entrySet()) current.put(entry.getKey(), entry.getValue().value());
	}
}
package net.hawthorn.dndsheets.client.gui.components;

import net.minecraft.client.gui.GuiGraphics;

/**
 * <p>Brass frame for the character sheet's slots: the text fields and the attack list.</p>
 *
 * <p>Vanilla draws both the same way —a one-pixel gray ring (white when focused) around a
 * black fill— and both colors are fixed inside {@code EditBox.renderWidget} and
 * {@code AbstractScrollWidget.renderBorder}. On parchment that reads as widgets borrowed from another
 * interface.</p>
 *
 * <p>Removing the border isn't an option for {@code EditBox}: {@code setBordered(false)} takes the
 * black fill with it AND moves the text (from centered-with-margin to flush against the top-left
 * corner), and without a dark background behind it the text would have to be ink on parchment — which with
 * Minecraft's fixed shadow reads as doubled. So the ring isn't removed: it's repainted over. It occupies exactly
 * one pixel outside the slot, meaning covering it touches neither the text nor the interior.</p>
 *
 * <p>Lives in this package and not alongside {@code GuiStyle} because both sides use it: the sheet
 * screen ({@code client.gui}) for its fields, and {@code RollScrollWidget} (here) for the attack list and
 * for each row's name. {@code GuiStyle} isn't visible from here.</p>
 */
public final class TomeField {

	//Same palette as GuiStyle and TomeButton. Duplicated deliberately: the components package can't see GuiStyle,
	//and a repeated color is less harmful than exposing the entire style class for just three integers.
	private static final int RING = 0xFF6B5636;
	private static final int RING_FOCUSED = 0xFFC9A227;
	private static final int SHADOW = 0xFF8A7B5E;
	/** Fill for a large slot (the attack list): leather, not pure black. */
	public static final int WELL_FILL = 0xFF15100A;

	private TomeField() {
	}

	/**
	 * <p>Repaints a slot's ring in brass, and adds shadow outside on the top and left —where
	 * light would come from in Minecraft's beveling— so it reads as sunken into the sheet.</p>
	 *
	 * <p>The coordinates are the RING's, meaning one pixel outside the widget.</p>
	 */
	public static void frame(GuiGraphics guiGraphics, int left, int top, int right, int bottom, boolean focused) {
		int ring = focused ? RING_FOCUSED : RING;

		guiGraphics.fill(left, top, right, top + 1, ring);
		guiGraphics.fill(left, bottom - 1, right, bottom, ring);
		guiGraphics.fill(left, top, left + 1, bottom, ring);
		guiGraphics.fill(right - 1, top, right, bottom, ring);

		guiGraphics.fill(left - 1, top - 1, right, top, SHADOW);
		guiGraphics.fill(left - 1, top - 1, left, bottom, SHADOW);
	}

	/** Overload for a widget: the ring sits just outside its rectangle. */
	public static void frameWidget(GuiGraphics guiGraphics, int x, int y, int width, int height, boolean focused) {
		frame(guiGraphics, x - 1, y - 1, x + width + 1, y + height + 1, focused);
	}
}
package net.hawthorn.dndsheets.client.gui.components;

import net.hawthorn.dndsheets.client.gui.GuiStyle;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.sounds.SoundManager;
import net.minecraft.network.chat.Component;

/**
 * <p>Section header within a list: the brass-colored label between two rules, with no row background.
 * Splits a long menu (the DM Panel reached 17 indistinguishable flat rows) into named blocks,
 * without inventing a second container: {@code ButtonListWidget} only knows about {@code Button}, so the
 * header IS a button — one that doesn't respond to clicks or keyboard and paints itself as a label. See
 * {@code ListPickerScreen.addHeader}, which also excludes it from the search.</p>
 */
public class SectionHeader extends Button {

	public SectionHeader(Component label, int width, int height) {
		super(0, 0, width, height, label, b -> {}, DEFAULT_NARRATION);
	}

	@Override
	public void renderWidget(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTick) {
		Font font = Minecraft.getInstance().font;
		int centerX = this.getX() + this.width / 2;
		int ruleY = this.getY() + this.height / 2;
		int halfText = font.width(this.getMessage()) / 2;

		GuiStyle.rule(guiGraphics, this.getX() + 6, centerX - halfText - 6, ruleY);
		GuiStyle.rule(guiGraphics, centerX + halfText + 6, this.getX() + this.width - 6, ruleY);
		guiGraphics.drawCenteredString(font, this.getMessage(), centerX, this.getY() + (this.height - 8) / 2, GuiStyle.ACCENT_COLOR);
	}

	//A label, not a control: no clicking, sound, or keyboard focus (ButtonListWidget re-enables
	//"active" every frame for visible rows, so the block has to happen through these methods and
	//not through active=false).
	@Override
	public boolean mouseClicked(double mouseX, double mouseY, int button) {
		return false;
	}

	@Override
	public void playDownSound(SoundManager soundManager) {
	}

	@Override
	public boolean isFocused() {
		return false;
	}
}

