51	
52		protected FormPanelScreen(Component title, int titleRows, Screen parent) {
53			super(title);
54			this.titleRows = titleRows;
55			this.parent = parent;
56		}
57	
58		/** Adds the panel's rows, in order, with addField(...)/addFieldRow(...)/addCycleButton(...). */
59		protected abstract void buildForm();
60	
61		/**
62		 * <p>A row's width. Defaults to {@link #FIELD_WIDTH}, which is what the screens that inherit from
63		 * {@link SmallFormScreen} have always used: as long as nobody overrides it, the arithmetic is
64		 * identical.</p>
65		 */
66		protected int formWidth() {
67			return FIELD_WIDTH;
68		}
69	
70		/** Vertical spacing between rows. A tight panel can lower it to fit more. */
71		protected int rowHeight() {
72			return ROW_HEIGHT;
73		}
74	
75		/** Height of the header band. A panel that paints a second line under the title needs more. */
76		protected int titleBand() {
77			return TITLE_BAND;
78		}
79	
80		/** Height per row for the initial centering: how many rows fit above the center. */
81		protected final void layoutTop() {
82			centerX = this.width / 2;
83			//Without this cap, a panel with many rows centered on height/2 pushed the first ones (and its
84			//title) off screen on short windows or with a high GUI Scale, instead of just ending up cramped:
85			//the top couldn't be seen or clicked.
86			formTop = Math.max(44, this.height / 2 - rowHeight() * titleRows);
87			cursorY = formTop;
88			editBoxes.clear();
89			editBoxLabels.clear();
90		}
