102			EditBox box = registerBox(label, defaultValue, maxLength, left, y, formWidth() - 24);
103			this.addRenderableWidget(net.hawthorn.dndsheets.client.gui.components.TomeButton.of(net.minecraft.network.chat.Component.literal("..."),
104				b -> ChoiceScreen.request(source, multi, box.getValue(), box::setValue), left + formWidth() - 20, y, 20, FIELD_HEIGHT));
105			return box;
106		}
