127		 * inside 190px, and when it wanted to fit a button into that same row it was left with 190-188 =
128		 * <b>2 pixels</b> of width, practically impossible to click. That's one of the project's two worst
129		 * layout bugs, and it comes straight from eyeballing the split.</p>
130		 */
131		protected EditBox[] addFieldRow(String[] labels, String[] defaults, int maxLength) {
132			int y = nextRowY();
133			int columns = labels.length;
134			int gap = 4;
135			int width = (formWidth() - gap * (columns - 1)) / columns;
136			int left = centerX - formWidth() / 2;
137	
138			EditBox[] boxes = new EditBox[columns];
139			for (int i = 0; i < columns; i++) {
140				boxes[i] = registerBox(labels[i], defaults[i], maxLength, left + i * (width + gap), y, width);
141			}
142			return boxes;
143		}
144	
145		private EditBox registerBox(String label, String defaultValue, int maxLength, int x, int y, int width) {
146			EditBox box = new EditBox(this.font, x, y, width, FIELD_HEIGHT, Component.literal(label));
147			//The cap FIRST and the value after, never the other way around. Both calls truncate: setValue cuts
148			//to whatever maxLength is worth AT THAT MOMENT, and a freshly constructed EditBox comes with 32 —
149			//vanilla's default — so filling in before raising the cap truncated every prefilled form to 32
150			//characters. It showed up two steps removed and wearing a different face: a saved encounter with
