LANG = 'src/main/resources/assets/dndsheets/lang/'
en = ("From the pack", "Editing one saves your own copy with the same id, and your copy is the one that counts.")
es = ("Del pack", "Editar una guarda tu propia copia con el mismo id, y tu copia es la que cuenta.")
for f in glob.glob(LANG + '*.json'):
    b = open(f, 'rb').read()
    nl = b'\r\n' if b'\r\n' in b else b'\n'
    lines = b.split(nl)
    i = next(i for i, l in enumerate(lines) if b'"gui.dndsheets.content_entry.from_pack"' in l)
    head, tip = en if f.endswith('en_us.json') else es
    lines[i] = ('  "gui.dndsheets.content_entry.from_pack": "%s",' % head).encode('utf-8')
    lines.insert(i + 1, ('  "gui.dndsheets.content_entry.from_pack_tip": "%s",' % tip).encode('utf-8'))
    out = nl.join(lines)
    json.loads(out.decode('utf-8'))
    open(f, 'wb').write(out)
