LANG = 'src/main/resources/assets/dndsheets/lang/'
for f in glob.glob(LANG + '*.json'):
    b = open(f, 'rb').read()
    nl = b'\r\n' if b'\r\n' in b else b'\n'
    lines = b.split(nl)
    assert not any(b'"gui.dndsheets.option.' in l for l in lines), f
    i = next(i for i, l in enumerate(lines) if b'"gui.dndsheets.' in l)
    vals = EN if f.endswith('en_us.json') else ES
    lines[i:i] = [('  "gui.dndsheets.option.%s": "%s",' % (k, v)).encode('utf-8') for k, v in vals.items()]
    out = nl.join(lines)
    json.loads(out.decode('utf-8'))
    open(f, 'wb').write(out)
