LANG = 'src/main/resources/assets/dndsheets/lang/'
for f in glob.glob(LANG + '*.json'):
    b = open(f, 'rb').read()
    nl = b'\r\n' if b'\r\n' in b else b'\n'
    lines = b.split(nl)
    i = next(i for i, l in enumerate(lines) if b'"gui.dndsheets.form.ac_bonus"' in l)
    en = f.endswith('en_us.json')
    lines[i:i] = [('  "gui.dndsheets.form.ac": "%s",' % ('Armor class' if en else 'Clase de armadura')).encode('utf-8'),
                  ('  "gui.dndsheets.form.hp": "%s",' % ('Hit points' if en else 'Puntos de golpe')).encode('utf-8')]
    out = nl.join(lines)
    json.loads(out.decode('utf-8'))
    open(f, 'wb').write(out)
