    nl = b'\r\n' if b'\r\n' in b else b'\n'
    lines = b.split(nl)
    en = f.endswith('en_us.json')
    i = next(i for i, l in enumerate(lines) if b'"gui.dndsheets.form.id"' in l)
    lines[i + 1:i + 1] = [('  "gui.dndsheets.form.pool": "%s",' % 'Pool').encode('utf-8'),
                          ('  "gui.dndsheets.form.tags": "%s",' % ('Tags' if en else 'Etiquetas')).encode('utf-8')]
    i = next(i for i, l in enumerate(lines) if b'"gui.dndsheets.dungeon_trace.facing_west"' in l)
    lines[i:i] = [b'  "gui.dndsheets.dungeon_trace.facing_east": "E",',
                  b'  "gui.dndsheets.dungeon_trace.facing_north": "N",',
                  b'  "gui.dndsheets.dungeon_trace.facing_south": "S",']
