	@Override
	protected boolean searchable() {
		return true;
	}

	@Override
	protected void buildRows() {
		for (String spellId : ids) {
			String name = OptionLabels.contentName("spell", spellId);
			addRow(Component.translatable("gui.dndsheets.spell_give.learn", name), b -> send(spellId, false));
			addRow(Component.translatable("gui.dndsheets.spell_give.staff", name), b -> send(spellId, true));
		}
	}

	private void send(String spellId, boolean asStaff) {
