@Override
protected void init() {
	applyCellSize();
	toolButtons.clear();
	readouts.clear();
	int rightX = dialogWidth() - MARGIN - RIGHT_COLUMN;

	//--- Left column: what the brush paints, and how ---
	//Swatch + outline mark the active tool (see render): disabling it, as before, greyed out the very
	//button the DM is using and read as "not available".
	int y = TOP_BAND;
	for (Tool tool : Tool.values()) {
		toolButtons.add(addModalButton(MARGIN, y, LEFT_COLUMN, BUTTON_HEIGHT, Component.translatable(tool.label), b -> currentTool = tool));
		y += ROW;
	}
	y += 4;
	addModalButton(MARGIN, y, LEFT_COLUMN, BUTTON_HEIGHT, Component.translatable("gui.dndsheets.dungeon_trace.undo_button"), b -> undo());
	y += ROW;
	modeButton = addModalButton(MARGIN, y, LEFT_COLUMN, BUTTON_HEIGHT, modeLabel(), b -> {
		paintMode = paintMode == PaintMode.FREE ? PaintMode.RECT : PaintMode.FREE;
		rectDragging = false;
		modeButton.setMessage(modeLabel());
	});
	modeButton.setTooltip(Tooltip.create(Component.translatable("gui.dndsheets.dungeon_trace.tip_mode")));
	y += ROW;
	addModalButton(MARGIN, y, LEFT_COLUMN, BUTTON_HEIGHT, Component.translatable("gui.dndsheets.dungeon_trace.circle_button"), b -> {
		pushUndo();
		GridToStructure.stampCircle(grid, gridSize / 2, gridSize / 2, gridSize / 2 - 1, 1);
	}).setTooltip(Tooltip.create(Component.translatable("gui.dndsheets.dungeon_trace.tip_circle")));
	y += ROW + 4;
	blockButton = addModalButton(MARGIN, y, LEFT_COLUMN, BUTTON_HEIGHT, blockLabel(), b -> BlockPickerScreen.open(this, id -> {
		currentObjectBlock = id;
		blockButton.setMessage(blockLabel());
		rememberRecent(id);
	}));
	blockButton.setTooltip(Tooltip.create(Component.translatable("gui.dndsheets.dungeon_trace.tip_object")));
	y += ROW;
	facingButton = addModalButton(MARGIN, y, LEFT_COLUMN, BUTTON_HEIGHT, facingLabel(), b -> {
		currentFacing = FACING_CYCLE[(indexOf(currentFacing) + 1) % FACING_CYCLE.length];
		facingButton.setMessage(facingLabel());
	});
	facingButton.setTooltip(Tooltip.create(Component.translatable("gui.dndsheets.dungeon_trace.tip_facing")));
	recentTop = y + ROW;
	rebuildRecentButtons();

	//--- Right column: the piece as a whole ---
	y = TOP_BAND;
	sizeButton = addModalButton(rightX, y, RIGHT_COLUMN, BUTTON_HEIGHT, sizeLabel(), b -> cycleSize());
	sizeButton.setTooltip(Tooltip.create(Component.translatable("gui.dndsheets.dungeon_trace.tip_size")));
	y += ROW;
	stepper(rightX, y, this::heightLabel, this::changeHeight, "gui.dndsheets.dungeon_trace.tip_height");
	y += ROW;
	wallBlockButton = addModalButton(rightX, y, RIGHT_COLUMN, BUTTON_HEIGHT, wallLabel(), b -> BlockPickerScreen.open(this, id -> {
		wallBlock = id;
		wallBlockButton.setMessage(wallLabel());
	}));
	y += ROW;
	floorBlockButton = addModalButton(rightX, y, RIGHT_COLUMN, BUTTON_HEIGHT, floorLabel(), b -> BlockPickerScreen.open(this, id -> {
		floorBlock = id;
		floorBlockButton.setMessage(floorLabel());
	}));
	y += ROW;

	//Label drawn above the box in render(): beside it, it ate half the box's width.
	poolLabelY = y;
	//Rebuilt by init() (window resize): keep what the DM typed.
	String doorPool = doorPoolBox != null ? doorPoolBox.getValue() : "";
	doorPoolBox = new EditBox(this.font, dialogLeft() + rightX, dialogTop() + y + 10, RIGHT_COLUMN, BUTTON_HEIGHT,
		Component.translatable("gui.dndsheets.dungeon_trace.door_pool"));
	doorPoolBox.setHint(Component.translatable("gui.dndsheets.dungeon_trace.door_pool_hint"));
	doorPoolBox.setMaxLength(32);
	doorPoolBox.setValue(doorPool);
	this.addRenderableWidget(doorPoolBox);
	y += 10 + ROW + 4;

	stepper(rightX, y, this::originXLabel, this::changeOriginDx, "gui.dndsheets.dungeon_trace.tip_origin");
	y += ROW;
	stepper(rightX, y, this::originZLabel, this::changeOriginDz, "gui.dndsheets.dungeon_trace.tip_origin");

	int bottom = dialogHeight() - MARGIN - 20;
	int half = (RIGHT_COLUMN - 4) / 2;
	addModalButton(rightX, bottom, half, 20, Component.translatable("gui.dndsheets.common.confirm"), b -> save());
	addModalButton(rightX + half + 4, bottom, half, 20, Component.translatable("gui.dndsheets.common.cancel"), b -> this.onClose());
}

/** "-  value  +": the value is drawn text (see render), not a disabled button that looked broken and greyed. */
private void stepper(int x, int y, java.util.function.Supplier<Component> label, java.util.function.IntConsumer change, String tip) {
	addModalButton(x, y, BUTTON_HEIGHT, BUTTON_HEIGHT, Component.literal("-"), b -> change.accept(-1)); //i18n-ok: symbol
	addModalButton(x + RIGHT_COLUMN - BUTTON_HEIGHT, y, BUTTON_HEIGHT, BUTTON_HEIGHT, Component.literal("+"), b -> change.accept(1)); //i18n-ok: symbol
	readouts.add(new Readout(dialogLeft() + x + BUTTON_HEIGHT + 2, dialogTop() + y, RIGHT_COLUMN - 2 * BUTTON_HEIGHT - 4, label, Component.translatable(tip)));
}

private Component wallLabel() {
	return materialLabel(I18n.get("gui.dndsheets.dungeon_trace.tool_wall"), wallBlock, RIGHT_COLUMN - 8);
}

private Component floorLabel() {
	return materialLabel(I18n.get("gui.dndsheets.dungeon_trace.tool_floor"), floorBlock, RIGHT_COLUMN - 8);
}

@Override
public void render(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTicks) {
	renderPanel(guiGraphics);
	guiGraphics.drawCenteredString(this.font, GuiStyle.title(this.title), dialogLeft() + dialogWidth() / 2, dialogTop() + 8, GuiStyle.TITLE_COLOR);

	int left = canvasLeft(), top = canvasTop();
	GuiStyle.inset(guiGraphics, left - 3, top - 3, left + canvas + 2, top + canvas + 2);
	for (int z = 0; z < gridSize; z++) {
		for (int x = 0; x < gridSize; x++) {
			int x1 = left + x * cell, y1 = top + z * cell;
			guiGraphics.fill(x1, y1, x1 + cell - 1, y1 + cell - 1, colorFor(grid[z][x]));
		}
	}
	//North marker: the facing buttons say N/E/S/W, and the grid's top edge is north.
	guiGraphics.drawCenteredString(this.font, Component.translatable("gui.dndsheets.dungeon_trace.facing_north"), left + canvas / 2, top - 12, GuiStyle.MUTED_COLOR);

	if (rectDragging) {
		int minX = Math.min(rectStartX, rectEndX), maxX = Math.max(rectStartX, rectEndX);
		int minZ = Math.min(rectStartZ, rectEndZ), maxZ = Math.max(rectStartZ, rectEndZ);
		int x1 = left + minX * cell, y1 = top + minZ * cell;
		int x2 = left + (maxX + 1) * cell, y2 = top + (maxZ + 1) * cell;
		guiGraphics.renderOutline(x1, y1, x2 - x1, y2 - y1, GuiStyle.ACCENT_COLOR);
	} else {
		//The cell the brush would paint, tinted with the active tool's colour.
		int[] at = cellAt(mouseX, mouseY);
		if (at != null) {
			int x1 = left + at[0] * cell, y1 = top + at[1] * cell;
			guiGraphics.fill(x1, y1, x1 + cell - 1, y1 + cell - 1, (colorFor(currentTool.cell) & 0xFFFFFF) | 0x99000000);
			guiGraphics.renderOutline(x1 - 1, y1 - 1, cell + 1, cell + 1, GuiStyle.ACCENT_COLOR);
		}
	}

	int poolX = dialogLeft() + dialogWidth() - MARGIN - RIGHT_COLUMN;
	guiGraphics.drawString(this.font, fit(I18n.get("gui.dndsheets.dungeon_trace.door_pool"), RIGHT_COLUMN), poolX, dialogTop() + poolLabelY + 1, GuiStyle.SUBTITLE_COLOR, false);

	super.render(guiGraphics, mouseX, mouseY, partialTicks);
	net.hawthorn.dndsheets.client.gui.components.TomeField.frameWidget(guiGraphics, doorPoolBox.getX(), doorPoolBox.getY(), doorPoolBox.getWidth(), doorPoolBox.getHeight(), doorPoolBox.isFocused());

	//Tool buttons double as the colour legend; the active one gets the brass ring (DESIGN.md §4).
	for (int i = 0; i < toolButtons.size(); i++) {
		Button button = toolButtons.get(i);
		Tool tool = Tool.values()[i];
		int sx = button.getX() + 4, sy = button.getY() + 4;
		guiGraphics.fill(sx - 1, sy - 1, sx + 9, sy + 9, GuiStyle.ACCENT_COLOR);
		guiGraphics.fill(sx, sy, sx + 8, sy + 8, colorFor(tool.cell));
		if (tool == currentTool) guiGraphics.renderOutline(button.getX() - 1, button.getY() - 1, button.getWidth() + 2, button.getHeight() + 2, GuiStyle.ACCENT_COLOR);
	}

	for (Readout readout : readouts) {
		GuiStyle.inset(guiGraphics, readout.x(), readout.y(), readout.x() + readout.width(), readout.y() + BUTTON_HEIGHT);
		guiGraphics.drawCenteredString(this.font, readout.text().get(), readout.x() + readout.width() / 2, readout.y() + 4, GuiStyle.SUBTITLE_COLOR);
		if (mouseX >= readout.x() && mouseX < readout.x() + readout.width() && mouseY >= readout.y() && mouseY < readout.y() + BUTTON_HEIGHT) {
			guiGraphics.renderTooltip(this.font, this.font.split(readout.tip(), 200), mouseX, mouseY);
		}
	}
}

