for f in glob.glob('src/main/resources/assets/dndsheets/lang/*.json'):
    b = open(f, 'rb').read(); nl = b'\r\n' if b'\r\n' in b else b'\n'
    en = f.endswith('en_us.json')
    d = json.loads(b.decode('utf-8'))
    for k in KEYS: assert k not in d, k
    lines = b.split(nl)
    end = max(i for i, l in enumerate(lines) if l.strip() == b'}')
    last = max(i for i in range(end) if lines[i].strip())
    if not lines[last].rstrip().endswith(b','): lines[last] = lines[last].rstrip() + b','
    new = [('  %s: %s,' % (json.dumps(k), json.dumps(v[0] if en else v[1], ensure_ascii=False))).encode('utf-8') for k, v in sorted(KEYS.items())]
    new[-1] = new[-1][:-1]
    lines[last + 1:last + 1] = new
    out = nl.join(lines); json.loads(out.decode('utf-8')); open(f, 'wb').write(out)
print('ok')

