340		 * <p>The block the Paint brush lays on a cell: the filled slots spread by the pattern — Solid takes the
341		 * first, Alternate checkers them by position (x+z), Random picks one. No slot filled = null, which
342		 * removes the paint (the cell goes back to the piece's material).</p>
343		 */
344		@Nullable
345		private ResourceLocation brushBlock(int x, int z) {
346			List<ResourceLocation> filled = new ArrayList<>();
347			for (ResourceLocation block : palette) if (block != null) filled.add(block);
348			if (filled.isEmpty()) return null;
349			return switch (pattern) {
350				case SOLID -> filled.get(0);
351				case ALTERNATE -> filled.get((x + z) % filled.size());
352				case RANDOM -> filled.get(random.nextInt(filled.size()));
353			};
354		}
