611		@Override
612		public boolean mouseClicked(double mouseX, double mouseY, int button) {
613			if (button == 0) {
614				int[] at = cellAt(mouseX, mouseY);
615				if (at != null) {
616					pushUndo();
617					if (paintMode == PaintMode.RECT) {
618						rectDragging = true;
619						rectStartX = rectEndX = at[0];
620						rectStartZ = rectEndZ = at[1];
621					} else {
