630		//Dragging the mouse paints as if it were click after click in Free mode — without this, a 12-cell
631		//wall is 12 separate clicks instead of one stroke. In Rectangle mode it only moves the preview; the
632		//fill is applied all at once on release (mouseReleased), not cell by cell.
633		@Override
634		public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
635			if (button == 0) {
636				int[] at = cellAt(mouseX, mouseY);
637				if (at != null) {
638					if (paintMode == PaintMode.RECT && rectDragging) {
639						rectEndX = at[0];
640						rectEndZ = at[1];
641					} else if (paintMode == PaintMode.FREE) {
642						paint(at[0], at[1]);
643					}
644					return true;
645				}
646			}
647			return super.mouseDragged(mouseX, mouseY, button, dragX, dragY);
648		}
