650		@Override
651		public boolean mouseReleased(double mouseX, double mouseY, int button) {
652			if (button == 0 && paintMode == PaintMode.RECT && rectDragging) {
653				int minX = Math.min(rectStartX, rectEndX), maxX = Math.max(rectStartX, rectEndX);
654				int minZ = Math.min(rectStartZ, rectEndZ), maxZ = Math.max(rectStartZ, rectEndZ);
655				for (int z = minZ; z <= maxZ; z++) for (int x = minX; x <= maxX; x++) paint(x, z);
656				rectDragging = false;
657				return true;
658			}
659			return super.mouseReleased(mouseX, mouseY, button);
660		}
