662		private void paint(int x, int z) {
663			if (x < 0 || x >= gridSize || z < 0 || z >= gridSize) return;
664			GridToStructure.Cell here = grid[z][x];
665			GridToStructure.CellOptions old = options[z][x];
666			if (currentTool == Tool.PAINT) {
667				//Only walls and floors have a material. Random keeps a cell already painted from the palette,
668				//or dragging over it would reshuffle it on every mouse move.
669				if (here != GridToStructure.Cell.WALL && here != GridToStructure.Cell.FLOOR) return;
670				if (pattern == Pattern.RANDOM && old.material() != null && java.util.Arrays.asList(palette).contains(old.material())) return;
671				options[z][x] = GridToStructure.CellOptions.painted(brushBlock(x, z));
672				return;
673			}
674			grid[z][x] = currentTool.cell;
675			options[z][x] = switch (currentTool) {
676				case OBJECT -> new GridToStructure.CellOptions(currentObjectBlock, currentFacing, null, null);
677				case DOOR, START -> new GridToStructure.CellOptions(null, null, doorPoolOverride(), currentFacing);
678				//Redrawing a wall as wall (or floor as floor) keeps its paint; changing the type drops it.
679				case WALL, FLOOR -> here == currentTool.cell ? old : GridToStructure.CellOptions.EMPTY;
680				default -> GridToStructure.CellOptions.EMPTY;
681			};
682		}
