684		private static int colorFor(GridToStructure.Cell cell) {
685			return switch (cell) {
686				case EMPTY -> 0xFF2B2B2B;
687				case FLOOR -> 0xFFB0A080;
688				case WALL -> 0xFF6B6B6B;
689				case DOOR -> 0xFF4A90D9;
690				case START -> 0xFF2ECC71;
691				case OBJECT -> 0xFFCC8844;
692			};
693		}
