705					guiGraphics.fill(x1, y1, x1 + cell - 1, y1 + cell - 1, colorFor(grid[z][x]));
706					//Painted: the block's own colour inside a rim of the cell type's, so wall and floor still read.
707					ResourceLocation material = options[z][x].material();
708					if (material != null && (grid[z][x] == GridToStructure.Cell.WALL || grid[z][x] == GridToStructure.Cell.FLOOR)) {
709						int rim = Math.max(1, cell / 5);
710						guiGraphics.fill(x1 + rim, y1 + rim, x1 + cell - 1 - rim, y1 + cell - 1 - rim, mapColor(material));
711					}
712				}
