714			//North marker: the facing buttons say N/E/S/W, and the grid's top edge is north.
715			guiGraphics.drawCenteredString(this.font, Component.translatable("gui.dndsheets.dungeon_trace.facing_north"), left + canvas / 2, top - 12, GuiStyle.MUTED_COLOR);
716	
717			if (rectDragging) {
718				int minX = Math.min(rectStartX, rectEndX), maxX = Math.max(rectStartX, rectEndX);
719				int minZ = Math.min(rectStartZ, rectEndZ), maxZ = Math.max(rectStartZ, rectEndZ);
720				int x1 = left + minX * cell, y1 = top + minZ * cell;
721				int x2 = left + (maxX + 1) * cell, y2 = top + (maxZ + 1) * cell;
722				guiGraphics.renderOutline(x1, y1, x2 - x1, y2 - y1, GuiStyle.ACCENT_COLOR);
723			} else {
724				//The cell the brush would paint, tinted with the active tool's colour.
725				int[] at = cellAt(mouseX, mouseY);
