import glob, json


def edit(p, pairs):
    s = open(p, encoding='utf-8').read(); crlf = '\r\n' in s; s = s.replace('\r\n', '\n')
    for a, b in pairs:
        assert s.count(a) == 1, (p, a); s = s.replace(a, b)
    if crlf: s = s.replace('\n', '\r\n')
    open(p, 'w', encoding='utf-8', newline='').write(s)


D = 'dungeon/src/main/java/net/hawthorn/dndsheets/dungeon/'

# ---------------- data model ----------------
edit(D + 'GridToStructure.java', [
('''	 * <p>{@code material} is the block a {@code WALL} column or a {@code FLOOR} cell is made of, painted cell
	 * by cell in the editor; null = the piece's wall/floor material.</p>
	 */
	public record CellOptions(ResourceLocation objectBlock, Direction objectFacing, String doorPool, Direction doorFacing, ResourceLocation material) {
		public static final CellOptions EMPTY = new CellOptions(null, null, null, null, null);

		public CellOptions(ResourceLocation objectBlock, Direction objectFacing, String doorPool, Direction doorFacing) {
			this(objectBlock, objectFacing, doorPool, doorFacing, null);
		}

		public static CellOptions painted(ResourceLocation material) {
			return material == null ? EMPTY : new CellOptions(null, null, null, null, material);
		}
	}''', '''	 * <p>{@code material} is the block a {@code WALL} column or a {@code FLOOR} cell is made of, painted cell
	 * by cell in the editor; null = the piece's wall/floor material. {@code holes} carves a {@code WALL}
	 * column: bit y-1 set = no block at height y (windows, gaps, wear).</p>
	 */
	public record CellOptions(ResourceLocation objectBlock, Direction objectFacing, String doorPool, Direction doorFacing,
			ResourceLocation material, int holes) {
		public static final CellOptions EMPTY = new CellOptions(null, null, null, null, null, 0);

		public CellOptions(ResourceLocation objectBlock, Direction objectFacing, String doorPool, Direction doorFacing) {
			this(objectBlock, objectFacing, doorPool, doorFacing, null, 0);
		}

		public static CellOptions painted(ResourceLocation material) {
			return EMPTY.withMaterial(material);
		}

