	/**
	 * <p>Stacked levels: level i's floor sits right on top of level i-1's walls (y = the heights below plus
	 * one floor per level), so a second storey is just a second grid. A {@code STAIRS} cell is a climbable
	 * column from its level's floor up through the next level's floor, which is left open above it.</p>
	 *
	 * @param heights wall height per level
	 * @param options per level; null (or a null level, or a null cell) = unadjusted
	 */
	public static List<PlacedBlock> renderLayers(List<Cell[][]> layers, int[] heights, List<CellOptions[][]> options) {
		List<PlacedBlock> blocks = new ArrayList<>();
		int base = 0;
		for (int i = 0; i < layers.size(); i++) {
			Cell[][] grid = layers.get(i);
			Cell[][] below = i > 0 ? layers.get(i - 1) : null;
			CellOptions[][] levelOptions = options != null ? options.get(i) : null;
			int height = heights[i];
			boolean levelAbove = i + 1 < layers.size();
			for (int z = 0; z < grid.length; z++) {
				for (int x = 0; x < grid[z].length; x++) {
					Cell cell = grid[z][x];
					if (cell == Cell.EMPTY) continue;
					CellOptions opt = optionsAt(levelOptions, x, z);
					//Open above a staircase from the level below: the stairs come up through here.
					boolean stairsBelow = below != null && z < below.length && x < below[z].length && below[z][x] == Cell.STAIRS;
					if (!stairsBelow) blocks.add(new PlacedBlock(x, base, z, Kind.FLOOR, null, cell == Cell.FLOOR ? opt.material() : null, null));
					switch (cell) {
						case WALL -> {
							for (int y = 1; y <= height; y++) {
								if (!opt.isHole(y)) blocks.add(new PlacedBlock(x, base + y, z, Kind.WALL, null, opt.blockAt(y), null));
							}
						}
						case OBJECT -> blocks.add(new PlacedBlock(x, base + 1, z, Kind.OBJECT, opt.objectFacing(), opt.objectBlock(), null));
						case DOOR, START -> {
							Kind kind = cell == Cell.START ? Kind.START : Kind.CONNECTOR;
							Direction facing = opt.doorFacing() != null ? opt.doorFacing() : outwardFacing(grid, x, z);
							//objectBlock on a door = what closes the doorway (a door, or the wall's block for a
							//hidden room). Closed, the doorway is 2 tall with wall above it, like a lintel.
							blocks.add(new PlacedBlock(x, base + 1, z, kind, facing, opt.objectBlock(), opt.doorPool()));
							if (opt.objectBlock() != null) {
								if (height >= 2) blocks.add(new PlacedBlock(x, base + 2, z, Kind.DOORWAY, facing, opt.objectBlock(), null));
								for (int y = 3; y <= height; y++) blocks.add(new PlacedBlock(x, base + y, z, Kind.WALL, null, null, null));
							}
						}
						case STAIRS -> {
							//One block further when there's a level above, so it pokes through that level's floor.
							int top = height + (levelAbove ? 1 : 0);
							for (int y = 1; y <= top; y++) blocks.add(new PlacedBlock(x, base + y, z, Kind.STAIRS, null, null, null));
						}
						default -> {}
					}
				}
			}
			base += height + 1;
		}
		return blocks;
	}

	private static CellOptions optionsAt(CellOptions[][] options, int x, int z) {
		if (options == null) return CellOptions.EMPTY;
		CellOptions opt = options[z][x];
		return opt != null ? opt : CellOptions.EMPTY;
	}

	/** Inverse of {@link Cell#fromChar}, so the editor can send the grid as text over the network. */
	public static char toChar(Cell cell) {
		return switch (cell) {
			case WALL -> '#';
			case FLOOR -> ',';
			case DOOR -> 'D';
			case START -> 'S';
			case OBJECT -> 'o';
			case STAIRS -> 'H';
			case EMPTY -> '.';
		};
	}

	public static List<PlacedBlock> translate(String[] rows, int height) {
		return render(parse(rows), height);
	}

	//ponytail: simple heuristic — the door points to the first empty neighbor found, in N/E/S/W order.
	//An interior door with no empty neighbor at all has no natural "outside" and defaults to pointing
	//north. If routing interior doors is ever needed, the editor will have to let the DM mark the
	//direction by hand.
	public static Direction outwardFacing(Cell[][] grid, int x, int z) {
		if (isOutside(grid, x, z - 1)) return Direction.NORTH;
		if (isOutside(grid, x + 1, z)) return Direction.EAST;
		if (isOutside(grid, x, z + 1)) return Direction.SOUTH;
		if (isOutside(grid, x - 1, z)) return Direction.WEST;
		return Direction.NORTH;
	}

	/** Whether a door at (x, z) has an empty neighbour to face; without one it can only point inward. */
	public static boolean hasOutside(Cell[][] grid, int x, int z) {
		return isOutside(grid, x, z - 1) || isOutside(grid, x + 1, z) || isOutside(grid, x, z + 1) || isOutside(grid, x - 1, z);
	}

	private static boolean isOutside(Cell[][] grid, int x, int z) {
		if (z < 0 || z >= grid.length || x < 0 || x >= grid[z].length) return true;
		return grid[z][x] == Cell.EMPTY;
	}

	/**
	 * <p>Stamps a circle onto an already-parsed grid: useful so the editor can offer a "circular room"
	 * brush instead of forcing the DM to mark cell by cell. Compares distance to the center, so the
	 * result comes out stair-stepped — recognizable as a circle, not geometrically exact.</p>
	 */
	public static void stampCircle(Cell[][] grid, int centerX, int centerZ, int radius, int wallThickness) {
		for (int z = 0; z < grid.length; z++) {
			for (int x = 0; x < grid[z].length; x++) {
				double dist = Math.hypot(x - centerX, z - centerZ);
				if (dist <= radius - wallThickness) grid[z][x] = Cell.FLOOR;
				else if (dist <= radius) grid[z][x] = Cell.WALL;
			}
		}
	}
}
	 * <p>Plants the blocks and nothing else. {@code connectors} false is a room pasted straight into the world
	 * (not a dungeon piece): doors and entrances are left as open doorways instead of jigsaw blocks, which
	 * would only mean something to the dungeon generator.</p>
	 */
	public static void place(ServerLevel level, BlockPos origin, List<GridToStructure.PlacedBlock> blocks, Materials materials,
			String pool, boolean connectors) {
		BlockState floorState = resolveOrDefault(materials.floorBlockId(), DEFAULT_FLOOR);
		BlockState wallState = resolveOrDefault(materials.wallBlockId(), DEFAULT_WALL);
		for (GridToStructure.PlacedBlock block : blocks) {
			BlockPos at = origin.offset(block.x(), block.y(), block.z());
			switch (block.kind()) {
				//A painted cell carries its own block; the rest use the piece's material.
				case FLOOR -> level.setBlock(at, resolveOrDefault(block.blockId(), floorState), 3);
				case WALL -> level.setBlock(at, resolveOrDefault(block.blockId(), wallState), 3);
				case OBJECT -> level.setBlock(at, objectStateFor(block.blockId(), block.facing()), 3);
				case STAIRS -> level.setBlock(at, DEFAULT_STAIRS, 3);
				case CONNECTOR, START -> {
					BlockState closed = block.blockId() != null ? doorwayState(block.blockId(), block.facing(), false) : null;
					if (connectors) placeJigsaw(level, at, block.facing(),
						block.targetPool() != null ? block.targetPool() : pool, block.kind() == GridToStructure.Kind.START, closed);
					else level.setBlock(at, closed != null ? closed : Blocks.AIR.defaultBlockState(), 2);
				}
				//Flag 2 (no neighbour updates): a door's lower half alone would pop off before its upper half lands.
				case DOORWAY -> level.setBlock(at, doorwayState(block.blockId(), block.facing(), true), 2);
			}
		}
	}

	public static BlockState resolveOrDefault(ResourceLocation blockId, BlockState fallback) {
		//containsKey, not just a null check: the block registry answers AIR for an id it doesn't know, so
		//an empty material ("" parses as "minecraft:") pasted walls and floors made of air.
		if (blockId == null || !ForgeRegistries.BLOCKS.containsKey(blockId)) return fallback;
		net.minecraft.world.level.block.Block block = ForgeRegistries.BLOCKS.getValue(blockId);
		return block != null ? block.defaultBlockState() : fallback;
	}

	//Rotates the object if its block uses the standard horizontal-facing property (most single-space
	//furniture has it, regardless of which mod it's from) — no list of known blocks needed, so no
	//special per-mod compatibility is required. Furniture spanning MORE than one cell (bed, door) won't
	//come out complete: each grid cell is a single BlockPos, and that's already a ceiling of the
	//editor, not of this function.
	public static BlockState objectStateFor(ResourceLocation blockId, Direction facing) {
		BlockState state = resolveOrDefault(blockId, DEFAULT_OBJECT);
		if (facing != null && facing.getAxis().isHorizontal()
				&& state.hasProperty(net.minecraft.world.level.block.state.properties.BlockStateProperties.HORIZONTAL_FACING)) {
			state = state.setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.HORIZONTAL_FACING, facing);
		}
		return state;
	}

	//The "outward" direction GridToStructure computed is already the horizontal Direction; the jigsaw
	//also needs an "up" for its full orientation (FrontAndTop) — DOWN/UP don't apply to openings on the
	//grid's plane, so it's always UP.
	/**
	 * <p>The block closing a doorway, lower or upper part: a door gets the matching half and faces along the
	 * opening; any other block (the wall's, for a hidden room) is just itself.</p>
	 */
	public static BlockState doorwayState(ResourceLocation blockId, Direction facing, boolean upper) {
		BlockState state = resolveOrDefault(blockId, Blocks.AIR.defaultBlockState());
		var half = net.minecraft.world.level.block.state.properties.BlockStateProperties.DOUBLE_BLOCK_HALF;
		if (state.hasProperty(half)) state = state.setValue(half, upper
			? net.minecraft.world.level.block.state.properties.DoubleBlockHalf.UPPER
			: net.minecraft.world.level.block.state.properties.DoubleBlockHalf.LOWER);
		var horizontal = net.minecraft.world.level.block.state.properties.BlockStateProperties.HORIZONTAL_FACING;
		if (facing != null && facing.getAxis().isHorizontal() && state.hasProperty(horizontal)) state = state.setValue(horizontal, facing);
		return state;
	}

	//closed != null: what the jigsaw turns into once the dungeon is generated (its "final state"), so
	//the connection point ends up as a door or a hidden wall instead of an open gap.
	private static void placeJigsaw(ServerLevel level, BlockPos at, Direction facing, String pool, boolean isStart, BlockState closed) {
		BlockState state = Blocks.JIGSAW.defaultBlockState()
			.setValue(JigsawBlock.ORIENTATION, FrontAndTop.fromFrontAndTop(facing, Direction.UP));
		level.setBlock(at, state, 3);
		BlockEntity entity = level.getBlockEntity(at);
		if (entity instanceof JigsawBlockEntity jigsaw) {
			DungeonManager.configureJigsaw(jigsaw, pool, isStart);
			if (closed != null) {
				jigsaw.setFinalState(net.minecraft.commands.arguments.blocks.BlockStateParser.serialize(closed));
				jigsaw.setChanged();
			}
		}
	}
}

