bits = d['cell_bit']
for k, v in d.items():
    if k not in ('cells',): print(' ', k, str(v)[:300])
cnt = {}
for row in cells:
    for c in row:
        for name, b in bits.items():
            if name not in ('nothing', 'label', 'room_id') and c & b: cnt[name] = cnt.get(name, 0) + 1
print('bit counts', cnt)

v = json.load(open(base + 'dungeon-map.dd2vtt'))
print('\ndd2vtt keys', list(v.keys()))
