nodes = m['state']['document']['nodes']
types = {}
for n in nodes.values(): types[n['type']] = types.get(n['type'], 0) + 1
print('node types', types)
for n in nodes.values():
    if n['type'] not in ('DOCUMENT', 'PAGE', 'TEMPLATE'):
        print(json.dumps(n)[:700]); print()

