	private static final java.nio.file.Path MAPS_DIR = DndPaths.ROOT.resolve("dungeon_maps").toAbsolutePath().normalize();

	private static List<String> mapFiles() {
		try {
			java.nio.file.Files.createDirectories(MAPS_DIR);
			try (var files = java.nio.file.Files.list(MAPS_DIR)) {
				return files.filter(java.nio.file.Files::isRegularFile).map(p -> p.getFileName().toString()).toList();
			}
		} catch (java.io.IOException e) {
			return List.of();
		}
	}

	/**
	 * <p>Pastes a generator's map (see DungeonMapImporter) with its north-west corner at the DM's feet:
	 * walls, floor, a ceiling, and the inside carved out, so it can go straight into a hillside or
	 * underground. Undo with /dnddungeon undopaste like a pasted room.</p>
	 */
	private static int importMap(CommandContext<CommandSourceStack> ctx, int scale, int height) throws CommandSyntaxException {
		ServerPlayer dm = ctx.getSource().getPlayerOrException();
		String name = StringArgumentType.getString(ctx, "file");
		mapFiles(); //creates the folder, so the "not found" message points at a folder that exists
		java.nio.file.Path file = MAPS_DIR.resolve(name).normalize();
		//Only files inside the maps folder: the name comes from chat.
		if (!file.startsWith(MAPS_DIR) || !java.nio.file.Files.isRegularFile(file)) {
			ctx.getSource().sendFailure(Component.translatable("chat.dndsheets.dungeon.map_missing", name, MAPS_DIR.toString()));
			return 0;
		}
		net.hawthorn.dndsheets.dungeon.DungeonMapImporter.Result map;
		try {
			map = net.hawthorn.dndsheets.dungeon.DungeonMapImporter.read(file, scale);
		} catch (java.io.IOException | RuntimeException e) {
			ctx.getSource().sendFailure(Component.translatable("chat.dndsheets.dungeon.map_failed", name, String.valueOf(e.getMessage())));
			return 0;
		}

		//A second level of height 0 is just a floor over everything: the ceiling.
		GridToStructure.Cell[][] grid = map.grid();
		GridToStructure.Cell[][] ceiling = new GridToStructure.Cell[grid.length][grid[0].length];
		for (int z = 0; z < grid.length; z++) {
			for (int x = 0; x < grid[z].length; x++) ceiling[z][x] = grid[z][x] == GridToStructure.Cell.EMPTY ? GridToStructure.Cell.EMPTY : GridToStructure.Cell.FLOOR;
		}
		List<GridToStructure.PlacedBlock> blocks = GridToStructure.renderLayers(List.of(grid, ceiling), new int[]{height, 0},
			java.util.Arrays.asList(map.options(), null));

		//The air inside, wherever the map places nothing: pasted into rock, the rooms would stay solid.
		java.util.Set<Long> placed = new java.util.HashSet<>();
		for (GridToStructure.PlacedBlock block : blocks) placed.add(BlockPos.asLong(block.x(), block.y(), block.z()));
		List<GridToStructure.PlacedBlock> carved = new java.util.ArrayList<>();
		for (int z = 0; z < grid.length; z++) {
			for (int x = 0; x < grid[z].length; x++) {
				if (grid[z][x] == GridToStructure.Cell.EMPTY || grid[z][x] == GridToStructure.Cell.WALL) continue;
				for (int y = 1; y <= height; y++) {
					if (!placed.contains(BlockPos.asLong(x, y, z))) carved.add(new GridToStructure.PlacedBlock(x, y, z, GridToStructure.Kind.FLOOR, null, null, null));
				}
			}
		}

		ServerLevel level = dm.serverLevel();
		BlockPos origin = dm.blockPosition();
		List<GridToStructure.PlacedBlock> touched = new java.util.ArrayList<>(blocks);
		touched.addAll(carved);
		net.hawthorn.dndsheets.dungeon.PasteHistory.record(dm, level, origin, touched);
		for (GridToStructure.PlacedBlock air : carved) {
			level.setBlock(origin.offset(air.x(), air.y(), air.z()), net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(), 2);
		}
		DungeonPiecePlacer.place(level, origin, blocks, DungeonPiecePlacer.Materials.DEFAULTS, "", false);
		ctx.getSource().sendSuccess(() -> Component.translatable("chat.dndsheets.dungeon.map_imported", map.format(), grid[0].length, grid.length,
				origin.getX(), origin.getY(), origin.getZ())
			.append(" ").append(Component.translatable("chat.dndsheets.dungeon.trace_paste_undo_link").withStyle(style -> style
				.withColor(net.minecraft.ChatFormatting.AQUA)
				.withClickEvent(new net.minecraft.network.chat.ClickEvent(net.minecraft.network.chat.ClickEvent.Action.RUN_COMMAND, "/dnddungeon undopaste")))), false);
		return 1;
	}
