1227		private void paint(int x, int z) {
1228			if (x < 0 || x >= gridSize || z < 0 || z >= gridSize) return;
1229			GridToStructure.Cell here = grid[z][x];
1230			GridToStructure.CellOptions old = options[z][x];
1231			if (currentTool == Tool.PAINT) {
1232				//Only walls and floors have a material. Random keeps a cell already painted from the palette,
1233				//or dragging over it would reshuffle it on every mouse move.
1234				if (here != GridToStructure.Cell.WALL && here != GridToStructure.Cell.FLOOR) return;
1235				if (pattern == Pattern.RANDOM && old.material() != null && java.util.Arrays.asList(palette).contains(old.material())) return;
1236				options[z][x] = paintCell(here, old, x, z);
1237				return;
1238			}
1239			grid[z][x] = currentTool.cell;
1240			options[z][x] = switch (currentTool) {
1241				case OBJECT -> new GridToStructure.CellOptions(currentObjectBlock, currentFacing, null, null);
1242				case DOOR, START -> new GridToStructure.CellOptions(currentDoorBlock, null, doorPoolOverride(), currentFacing);
1243				case STAIRS -> new GridToStructure.CellOptions(currentStairsBlock, currentFacing != null && currentFacing.getAxis().isHorizontal() ? currentFacing : null, null, null);
1244				//Redrawing a wall as wall (or floor as floor) keeps its paint; changing the type drops it.
1245				case WALL, FLOOR -> here == currentTool.cell ? old : GridToStructure.CellOptions.EMPTY;
1246				default -> GridToStructure.CellOptions.EMPTY;
1247			};
1248		}
