153		static Result fromUniversalVtt(JsonObject json, int scale) {
154			JsonObject resolution = json.getAsJsonObject("resolution");
155			JsonObject size = resolution.getAsJsonObject("map_size");
156			JsonObject origin = resolution.has("map_origin") ? resolution.getAsJsonObject("map_origin") : new JsonObject();
157			double ox = origin.has("x") ? origin.get("x").getAsDouble() : 0, oy = origin.has("y") ? origin.get("y").getAsDouble() : 0;
158			Canvas canvas = new Canvas(size.get("x").getAsDouble(), size.get("y").getAsDouble(), scale);
159			for (String key : new String[]{"line_of_sight", "objects_line_of_sight"}) {
160				if (!json.has(key)) continue;
161				for (JsonElement line : json.getAsJsonArray(key)) {
162					JsonArray points = line.getAsJsonArray();
163					for (int i = 0; i + 1 < points.size(); i++) {
164						JsonObject a = points.get(i).getAsJsonObject(), b = points.get(i + 1).getAsJsonObject();
165						canvas.wall(a.get("x").getAsDouble() - ox, a.get("y").getAsDouble() - oy, b.get("x").getAsDouble() - ox, b.get("y").getAsDouble() - oy);
166					}
167				}
168			}
169			if (json.has("portals")) {
170				for (JsonElement element : json.getAsJsonArray("portals")) {
171					JsonArray bounds = element.getAsJsonObject().getAsJsonArray("bounds");
172					JsonObject a = bounds.get(0).getAsJsonObject(), b = bounds.get(1).getAsJsonObject();
173					canvas.doorway(a.get("x").getAsDouble() - ox, a.get("y").getAsDouble() - oy, b.get("x").getAsDouble() - ox, b.get("y").getAsDouble() - oy, WOODEN_DOOR, false);
174				}
175			}
176			//No floor in the format: the floor is what the walls (and closed doors) shut off from the map's edge.
177			canvas.floorEnclosed();
