181		// ---------------- Dungeon Scrawl ----------------
182	
183		static Result fromDungeonScrawl(JsonObject json, int scale) {
184			JsonObject nodes = json.getAsJsonObject("state").getAsJsonObject("document").getAsJsonObject("nodes");
185			JsonObject geometry = json.getAsJsonObject("data").getAsJsonObject("geometry");
186			double cellSize = 36;
187			List<String> shapes = new ArrayList<>(), doors = new ArrayList<>();
188			for (var entry : nodes.entrySet()) {
189				JsonObject node = entry.getValue().getAsJsonObject();
190				String type = node.get("type").getAsString();
191				if (type.equals("PAGE") && node.has("grid")) cellSize = node.getAsJsonObject("grid").get("cellDiameter").getAsDouble();
192				//The dungeon's outline is the geometry each map template points at; doors are geometries under a door asset.
193				if (type.equals("TEMPLATE") && node.has("template")) {
194					String shape = node.getAsJsonObject("template").get("dungeonShape").getAsString();
195					if (nodes.has(shape)) shapes.add(nodes.getAsJsonObject(shape).get("geometryId").getAsString());
196				}
197				if (type.equals("GEOMETRY") && node.has("parentId") && nodes.has(node.get("parentId").getAsString())) {
198					JsonObject parent = nodes.getAsJsonObject(node.get("parentId").getAsString());
199					if (parent.has("kind") && "door".equals(parent.get("kind").getAsString())) doors.add(node.get("geometryId").getAsString());
200				}
201			}
202			//Pixels -> squares, shifted so the dungeon starts at 0,0.
203			List<double[][]> rings = new ArrayList<>(), lines = new ArrayList<>();
204			for (String id : shapes) collect(geometry.getAsJsonObject(id), cellSize, rings, lines);
205			if (rings.isEmpty()) throw new IllegalArgumentException("the Dungeon Scrawl map has no dungeon shape");
206			double minX = Double.MAX_VALUE, minY = Double.MAX_VALUE, maxX = -Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
207			for (double[][] ring : rings) {
208				for (double[] p : ring) {
209					minX = Math.min(minX, p[0]); minY = Math.min(minY, p[1]);
210					maxX = Math.max(maxX, p[0]); maxY = Math.max(maxY, p[1]);
211				}
212			}
213			Canvas canvas = new Canvas(maxX - minX, maxY - minY, scale);
214			canvas.floorInside(rings, minX, minY);
215			for (double[][] ring : rings) {
216				for (int i = 0; i < ring.length; i++) {
217					double[] a = ring[i], b = ring[(i + 1) % ring.length];
218					canvas.wall(a[0] - minX, a[1] - minY, b[0] - minX, b[1] - minY);
219				}
220			}
221			for (double[][] line : lines) {
222				for (int i = 0; i + 1 < line.length; i++) canvas.wall(line[i][0] - minX, line[i][1] - minY, line[i + 1][0] - minX, line[i + 1][1] - minY);
223			}
224			for (String id : doors) {
225				if (!geometry.has(id)) continue;
226				List<double[][]> doorRings = new ArrayList<>(), doorLines = new ArrayList<>();
227				collect(geometry.getAsJsonObject(id), cellSize, doorRings, doorLines);
228				for (double[][] line : doorLines) {
229					for (int i = 0; i + 1 < line.length; i++) canvas.wall(line[i][0] - minX, line[i][1] - minY, line[i + 1][0] - minX, line[i + 1][1] - minY);
230				}
231				//The door's leaf: a thin rectangle; the door goes along its long side, through its middle.
232				for (double[][] ring : doorRings) {
233					double x0 = Double.MAX_VALUE, y0 = Double.MAX_VALUE, x1 = -Double.MAX_VALUE, y1 = -Double.MAX_VALUE;
234					for (double[] p : ring) {
235						x0 = Math.min(x0, p[0]); y0 = Math.min(y0, p[1]);
236						x1 = Math.max(x1, p[0]); y1 = Math.max(y1, p[1]);
237					}
238					double cx = (x0 + x1) / 2 - minX, cy = (y0 + y1) / 2 - minY;
239					if (x1 - x0 >= y1 - y0) canvas.doorway(x0 - minX, cy, x1 - minX, cy, WOODEN_DOOR, false);
240					else canvas.doorway(cx, y0 - minY, cx, y1 - minY, WOODEN_DOOR, false);
241				}
242			}
243			return canvas.build("Dungeon Scrawl", List.of());
244		}
