246		private static void collect(JsonObject geometry, double cellSize, List<double[][]> rings, List<double[][]> lines) {
247			if (geometry.has("polygons")) {
248				for (JsonElement polygon : geometry.getAsJsonArray("polygons")) {
249					for (JsonElement ring : polygon.getAsJsonArray()) rings.add(points(ring.getAsJsonArray(), cellSize));
250				}
251			}
252			if (geometry.has("polylines")) {
253				for (JsonElement line : geometry.getAsJsonArray("polylines")) lines.add(points(line.getAsJsonArray(), cellSize));
254			}
255		}
256	
257		private static double[][] points(JsonArray array, double cellSize) {
258			double[][] points = new double[array.size()][];
259			for (int i = 0; i < array.size(); i++) {
260				JsonArray p = array.get(i).getAsJsonArray();
261				points[i] = new double[]{p.get(0).getAsDouble() / cellSize, p.get(1).getAsDouble() / cellSize};
262			}
263			return points;
264		}
