266		// ---------------- the block canvas ----------------
267	
268		private static final class Canvas {
269			final int scale, width, height;
270			final boolean[][] floor, wall, stairs;
271			final Direction[][] doorFacing;
272			final ResourceLocation[][] doorBlock;
273	
274			Canvas(double squaresWide, double squaresHigh, int scale) {
275				this.scale = scale;
276				this.width = (int) Math.ceil(squaresWide * scale) + 1;
277				this.height = (int) Math.ceil(squaresHigh * scale) + 1;
278				if (width > MAX_SIDE || height > MAX_SIDE) {
279					throw new IllegalArgumentException("the map would be " + width + " x " + height + " blocks (max " + MAX_SIDE + "): use a smaller scale");
280				}
281				floor = new boolean[height][width];
282				wall = new boolean[height][width];
283				stairs = new boolean[height][width];
284				doorFacing = new Direction[height][width];
285				doorBlock = new ResourceLocation[height][width];
286			}
287	
288			int block(double squares, int size) {
289				return Math.max(0, Math.min(size - 1, (int) Math.floor(squares * scale + 1e-6)));
290			}
291	
292			void fillSquare(int x, int z) {
293				for (int bz = z * scale; bz < (z + 1) * scale && bz < height; bz++) {
294					for (int bx = x * scale; bx < (x + 1) * scale && bx < width; bx++) floor[bz][bx] = true;
295				}
296			}
297	
298			//Small steps along the segment: diagonal walls come out as a block staircase with no gaps a fill could leak through.
299			void wall(double x1, double z1, double x2, double z2) {
300				int steps = (int) Math.ceil(Math.max(Math.abs(x2 - x1), Math.abs(z2 - z1)) * scale * 2) + 1;
301				for (int i = 0; i <= steps; i++) {
302					double t = (double) i / steps;
303					wall[block(z1 + (z2 - z1) * t, height)][block(x1 + (x2 - x1) * t, width)] = true;
304				}
305			}
306	
307			/** A wall line with a door at its middle; {@code hidden} = all wall (a secret door). */
308			void doorway(double x1, double z1, double x2, double z2, ResourceLocation block, boolean hidden) {
309				wall(x1, z1, x2, z2);
310				if (hidden) return;
311				int bx = block((x1 + x2) / 2, width), bz = block((z1 + z2) / 2, height);
312				//The way through crosses the wall line.
313				doorFacing[bz][bx] = Math.abs(x2 - x1) >= Math.abs(z2 - z1) ? Direction.NORTH : Direction.EAST;
314				doorBlock[bz][bx] = block;
315			}
316	
317			void stairs(double x, double z) {
318				stairs[block(z, height)][block(x, width)] = true;
319			}
320	
321			/** Floor = every block the walls shut off from the edge (4-way fill, so diagonal walls hold). */
322			void floorEnclosed() {
323				boolean[][] outside = new boolean[height][width];
324				ArrayDeque<int[]> queue = new ArrayDeque<>();
325				for (int x = 0; x < width; x++) { queue.add(new int[]{x, 0}); queue.add(new int[]{x, height - 1}); }
326				for (int z = 0; z < height; z++) { queue.add(new int[]{0, z}); queue.add(new int[]{width - 1, z}); }
327				while (!queue.isEmpty()) {
328					int[] p = queue.poll();
329					int x = p[0], z = p[1];
330					if (x < 0 || z < 0 || x >= width || z >= height || outside[z][x] || wall[z][x] || doorFacing[z][x] != null) continue;
331					outside[z][x] = true;
332					queue.add(new int[]{x + 1, z}); queue.add(new int[]{x - 1, z});
333					queue.add(new int[]{x, z + 1}); queue.add(new int[]{x, z - 1});
334				}
335				for (int z = 0; z < height; z++) {
336					for (int x = 0; x < width; x++) floor[z][x] = !outside[z][x] && !wall[z][x];
337				}
338			}
339	
340			/** Floor = block centres inside the outline (even-odd over every ring, so holes stay holes). */
341			void floorInside(List<double[][]> rings, double minX, double minZ) {
342				for (int bz = 0; bz < height; bz++) {
343					double pz = (bz + 0.5) / scale + minZ;
344					for (int bx = 0; bx < width; bx++) {
345						double px = (bx + 0.5) / scale + minX;
346						boolean inside = false;
347						for (double[][] ring : rings) {
348							for (int i = 0, j = ring.length - 1; i < ring.length; j = i++) {
349								if ((ring[i][1] > pz) != (ring[j][1] > pz)
350									&& px < (ring[j][0] - ring[i][0]) * (pz - ring[i][1]) / (ring[j][1] - ring[i][1]) + ring[i][0]) inside = !inside;
351							}
352						}
353						floor[bz][bx] = inside;
354					}
355				}
356			}
357	
358			Result build(String format, List<GridToStructure.Note> notes) {
359				GridToStructure.Cell[][] grid = new GridToStructure.Cell[height][width];
360				GridToStructure.CellOptions[][] options = new GridToStructure.CellOptions[height][width];
361				for (int z = 0; z < height; z++) {
362					for (int x = 0; x < width; x++) {
363						GridToStructure.Cell cell;
364						if (doorFacing[z][x] != null) {
365							cell = GridToStructure.Cell.DOOR;
366							options[z][x] = new GridToStructure.CellOptions(doorBlock[z][x], null, null, doorFacing[z][x]);
367						} else if (wall[z][x]) cell = touchesFloor(x, z) ? GridToStructure.Cell.WALL : GridToStructure.Cell.EMPTY;
368						else if (stairs[z][x]) cell = GridToStructure.Cell.STAIRS;
369						else if (floor[z][x]) cell = GridToStructure.Cell.FLOOR;
370						//Whatever the map left open around its floor gets closed.
371						else cell = touchesFloor(x, z) ? GridToStructure.Cell.WALL : GridToStructure.Cell.EMPTY;
372						grid[z][x] = cell;
373					}
374				}
375				return new Result(grid, options, format, notes);
376			}
377	
378			private boolean touchesFloor(int x, int z) {
379				for (int dz = -1; dz <= 1; dz++) {
380					for (int dx = -1; dx <= 1; dx++) {
381						int nx = x + dx, nz = z + dz;
382						if (nx >= 0 && nz >= 0 && nx < width && nz < height && floor[nz][nx] && !wall[nz][nx]) return true;
383					}
384				}
385				return false;
386			}
387		}
388	}
